begin;
    with j as (select * from jsonb_to_recordset($law7v002$[{"code_id":"APK_RF","article_number":"184","version_date":"2002-07-24","article_text":"1. Арбитражный суд выносит определения в случаях, предусмотренных настоящим Кодексом, и в других случаях по вопросам, требующим разрешения в ходе судебного разбирательства.\n\n2. Определение выносится арбитражным судом в виде отдельного судебного акта или протокольного определения.\n\nОпределение арбитражного суда в виде отдельного судебного акта выполняется в форме электронного документа. При отсутствии в арбитражном суде технической возможности для выполнения определения в форме электронного документа определение выполняется на бумажном носителе.\n\nПри выполнении определения в форме электронного документа дополнительно выполняется экземпляр данного определения на бумажном носителе.\n\nИзготовление определения арбитражного суда в виде отдельного судебного акта в полном объеме может быть отложено на срок, не превышающий десяти дней. Дата изготовления определения в полном объеме считается датой вынесения определения. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n(Часть в редакции Федерального закона от 23.06.2016 № 220-ФЗ)\n\n3. Определение в виде отдельного судебного акта арбитражный суд выносит во всех случаях, если настоящим Кодексом предусмотрена возможность обжалования определения отдельно от обжалования судебного акта, которым заканчивается рассмотрение дела по существу.\n\nВ других случаях арбитражный суд вправе вынести определение как в виде отдельного судебного акта, так и в виде протокольного определения.\n\n4. Определение в виде отдельного судебного акта арбитражный суд выносит в условиях, обеспечивающих тайну совещания судей, по правилам, установленным для принятия решения.\n\n5. Протокольное определение может быть вынесено арбитражным судом без удаления из зала судебного заседания. В случае, если дело рассматривается в коллегиальном составе, судьи совещаются по вопросам, связанным с вынесением такого определения, на месте, в зале судебного заседания. Протокольное определение объявляется устно и заносится в протокол судебного заседания.","article_title":"Статья 184. Вынесение арбитражным судом определений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ed3dce08b6f2b2c3f530a53813a8f59725a3085fc619728f2f7897274fb6470b"},{"code_id":"APK_RF","article_number":"185","version_date":"2002-07-24","article_text":"1. В определении должны быть указаны:\n\n1) дата и место вынесения определения;\n\n2) наименование арбитражного суда, состав суда, фамилия лица, которое вело протокол судебного заседания;\n\n3) наименование и номер дела;\n\n4) наименования лиц, участвующих в деле;\n\n5) вопрос, по которому выносится определение;\n\n6) мотивы, по которым арбитражный суд пришел к своим выводам, принял или отклонил доводы лиц, участвующих в деле, со ссылкой на законы и иные нормативные правовые акты;\n\n7) вывод по результатам рассмотрения судом вопроса;\n\n8) порядок и срок обжалования определения.\n\nОпределение, выносимое в виде отдельного судебного акта, подписывается судьей или составом арбитражного суда, вынесшими это определение.\n\n2. В протокольном определении должны быть указаны вопрос, по которому выносится определение, мотивы, по которым суд пришел к своим выводам, и вывод по результатам рассмотрения вопроса.","article_title":"Статья 185. Содержание определения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24296633569fa6d0bfc3e53b7a115d26bbb77084659cccf684e5f5f3973e53f2"},{"code_id":"APK_RF","article_number":"186","version_date":"2002-07-24","article_text":"По ходатайству указанных лиц копии определения, вынесенного в виде отдельного судебного акта, на бумажном носителе могут быть направлены им в пятидневный срок со дня поступления соответствующего ходатайства в арбитражный суд заказным письмом с уведомлением о вручении или вручены им под расписку.\n\n(Статья в редакции Федерального закона от 23.06.2016 № 220-ФЗ)","article_title":"Статья 186. Направление определения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7aea92f8ff702dc7acbede80c0203e30c9e7ecba1963b9a5cb7cc5fcb081ad8e"},{"code_id":"APK_RF","article_number":"187","version_date":"2002-07-24","article_text":"Определение, вынесенное арбитражным судом, исполняется немедленно, если иное не установлено настоящим Кодексом или арбитражным судом.","article_title":"Статья 187. Исполнение определения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fee8902cadeb4daeaa6691b9e45cfb82d0722734a88188a7ddac68297592433c"},{"code_id":"APK_RF","article_number":"188","version_date":"2002-07-24","article_text":"1. Определение арбитражного суда может быть обжаловано отдельно от обжалования судебного акта, которым заканчивается рассмотрение дела по существу, в случаях, если в соответствии с настоящим Кодексом предусмотрено обжалование этого определения, а также если это определение препятствует дальнейшему движению дела.\n\n2. В отношении определения, обжалование которого не предусмотрено настоящим Кодексом, а также в отношении протокольного определения могут быть заявлены возражения при обжаловании судебного акта, которым заканчивается рассмотрение дела по существу.","article_title":"Статья 188. Порядок и сроки обжалования определений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a8c8f386c2b49a325de8de4751d893203b6326dbe35e8925a20475712207fcc5"},{"code_id":"APK_RF","article_number":"188.1","version_date":"2002-07-24","article_text":"1. При выявлении в ходе рассмотрения дела случаев, требующих устранения нарушения законодательства Российской Федерации государственным органом, органом местного самоуправления, иным органом, организацией, наделенной федеральным законом отдельными государственными или иными публичными полномочиями, должностным лицом, адвокатом, субъектом профессиональной деятельности, арбитражный суд вправе вынести частное определение.\n\n2. Частное определение арбитражного суда направляется в соответствующий орган, организацию, наделенную федеральным законом отдельными государственными или иными публичными полномочиями, должностному лицу, а в случае нарушения законодательства Российской Федерации адвокатом, субъектом профессиональной деятельности - соответственно в адвокатское образование, саморегулируемую организацию, которые в течение месяца со дня его получения обязаны сообщить о принятых ими мерах.\n\n3. Неисполнение частного определения арбитражного суда влечет за собой ответственность, предусмотренную законодательством Российской Федерации. Привлечение к ответственности указанных в части 1 настоящей статьи лиц не освобождает их от обязанности сообщить о мерах, принятых по частному определению арбитражного суда.\n\n(Дополнение статьей - Федеральный закон от 02.03.2016 № 47-ФЗ)\n\nРАЗДЕЛ III. ПРОИЗВОДСТВО В АРБИТРАЖНОМ СУДЕ ПЕРВОЙ ИНСТАНЦИИ ПО ДЕЛАМ, ВОЗНИКАЮЩИМ ИЗ АДМИНИСТРАТИВНЫХ И ИНЫХ ПУБЛИЧНЫХ ПРАВООТНОШЕНИЙ","article_title":"Статья 188.1. Частные определения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"40ff5a749a66f2812609e843fa58d4d72d378d2c22a78c4202fb1584ec9d9539"},{"code_id":"APK_RF","article_number":"189","version_date":"2002-07-24","article_text":"1. Дела, возникающие из административных и иных публичных правоотношений, рассматриваются по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными в настоящем разделе, если иные правила административного судопроизводства не предусмотрены федеральным законом.","article_title":"Статья 189. Порядок рассмотрения дел, возникающих из административных и иных публичных правоотношений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8cedee9da6e86f75496a0f485498d116a3afda609fbe29cec9554199307f8542"},{"code_id":"APK_RF","article_number":"19","version_date":"2002-07-24","article_text":"1. Арбитражные заседатели могут быть привлечены к рассмотрению дел в арбитражных судах первой инстанции в соответствии с настоящим Кодексом и другими федеральными законами по ходатайству стороны в связи с особой сложностью дела и (или) необходимостью использования специальных знаний в сфере экономики, финансов, управления.\n\n2. Ходатайство о рассмотрении дела с участием арбитражных заседателей должно содержать обоснование особой сложности дела и (или) необходимости использования специальных знаний и может быть заявлено стороной не позднее чем за один месяц до начала судебного разбирательства, в том числе при каждом новом рассмотрении дела.\n\nСуд обязан разъяснить сторонам их право заявлять такое ходатайство в определении о принятии искового заявления к производству суда и при подготовке дела к судебному разбирательству.\n\n3. Ходатайство о рассмотрении дела с участием арбитражных заседателей разрешается арбитражным судом в порядке, установленном статьей 159 настоящего Кодекса.\n\nВ случае, если ходатайство о рассмотрении дела с участием арбитражных заседателей удовлетворено, кандидатуры арбитражных заседателей определяются из списка арбитражных заседателей, утвержденного в установленном федеральным законом порядке, с учетом их специализации, путем случайной выборки с использованием автоматизированной информационной системы или иным способом, применяемым в арбитражном суде для формирования состава суда.\n\n4. Наличие случая, предусмотренного частями 3 и 4 статьи 18 настоящего Кодекса, является основанием для замены арбитражного заседателя. В этом случае другая кандидатура арбитражного заседателя определяется в порядке, установленном частью 3 настоящей статьи.\n\nЕсли после отвода одного или нескольких арбитражных заседателей невозможно сформировать состав суда для рассмотрения дела с участием арбитражных заседателей, указанное дело рассматривается судьей единолично.\n\nВ случае неявки в судебное заседание одного или двух арбитражных заседателей дело может быть рассмотрено судьей единолично, если стороны или их представители присутствуют в данном судебном заседании и не возражают против рассмотрения дела судьей единолично.\n\nЕсли хотя бы одна из сторон возражает против рассмотрения дела судьей единолично, суд объявляет перерыв в судебном заседании или откладывает судебное разбирательство. Если проведение нового судебного заседания невозможно вследствие неявки в судебное заседание одного или двух арбитражных заседателей, суд по ходатайству одной из сторон вправе вынести определение о рассмотрении дела судьей единолично и открыть судебное заседание в первой инстанции.\n\n5. При рассмотрении дела арбитражные заседатели пользуются правами и несут обязанности судьи.\n\n6. Судья и арбитражный заседатель при рассмотрении дела, разрешении всех вопросов, возникающих при рассмотрении дела и принятии судебных актов, пользуются равными процессуальными правами.\n\n7. Арбитражный заседатель не может быть председательствующим в судебном заседании.\n\n(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 19. Привлечение к рассмотрению дел арбитражных заседателей","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24483ab7a2ef5527ab73e723109f16c0526283b2870dc33239bacad59022a0e8"},{"code_id":"APK_RF","article_number":"190","version_date":"2002-07-24","article_text":"1. Экономические споры, возникающие из административных и иных публичных правоотношений, могут быть урегулированы сторонами путем использования примирительных процедур по правилам, установленным в главе 15 настоящего Кодекса, поскольку иное не установлено настоящим Кодексом, другими законами и не вытекает из существа соответствующих правоотношений.\n\n2. В случаях, если до обращения в арбитражный суд с требованиями об оспаривании ненормативных правовых актов, решений и действий (бездействия) органов, осуществляющих публичные полномочия, и должностных лиц, о взыскании обязательных платежей и санкций стороны не использовали досудебное урегулирование спора, арбитражный суд вправе при согласии организации, индивидуального предпринимателя или гражданина в целях примирения сторон и уточнения фактических обстоятельств, снятия противоречий в позициях, в том числе путем проведения сверки взаимных расчетов, отложить судебное разбирательство в порядке, установленном настоящим Кодексом, предложив сторонам использовать примирительную процедуру, в том числе с участием судебного примирителя.\n\n3. Результатами примирения сторон по спорам, возникающим из административных и иных публичных правоотношений, могут быть, в частности:\n\n1) признание обстоятельств дела, соглашение сторон по обстоятельствам дела;\n\n2) соглашение сторон, содержащее квалификацию сделки, совершенной лицом, участвующим в деле, или статуса и характера деятельности этого лица;\n\n3) частичный или полный отказ от тр\n\nебований, частичное или полное признание требований, в том числе вследствие достижения сторонами соглашения об оценке обстоятельств в целом или их отдельных частей;\n\n4) мировое соглашение, если к полномочиям соответствующего административного органа, участвующего в деле, федеральным законом отнесено заключение мировых соглашений.\n\n(Статья в редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n(Наименование в редакции Федерального закона от 15.02.2016 № 18-ФЗ)","article_title":"Статья 190. Примирение сторон по спорам, возникающим из административных и иных публичных правоотношений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ed53bdf90a4d14766d16936c1db4f50d44ae4df7d8b8c2d572ec89bedf3c2258"},{"code_id":"APK_RF","article_number":"191","version_date":"2002-07-24","article_text":"1. Дела об оспаривании нормативных правовых актов федеральных органов исполнительной власти в сфере патентных прав и прав на селекционные достижения, права на топологии интегральных микросхем, права на секреты производства (ноу-хау), права на средства индивидуализации юридических лиц, товаров, работ, услуг и предприятий, права использования результатов интеллектуальной деятельности в составе единой технологии (далее в настоящей главе - нормативный правовой акт) рассматриваются Судом по интеллектуальным правам по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными в настоящей главе.\n\n2. Производство по делам об оспаривании нормативных правовых актов возбуждается на основании заявлений заинтересованных лиц, обратившихся с требованием о признании такого оспариваемого акта недействующим.\n\n(Статья в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 191. Порядок рассмотрения дел об оспаривании нормативных правовых актов Судом по интеллектуальным правам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dddb9f06b74a746b2b865f639188ef5ddb3bef75156c618299664a6e235ae45d"},{"code_id":"APK_RF","article_number":"192","version_date":"2002-07-24","article_text":"1. Граждане, организации и иные лица вправе обратиться в Суд по интеллектуальным правам с заявлениями о признании недействующими нормативных правовых актов, если полагают, что такой оспариваемый нормативный правовой акт или отдельные его положения не соответствуют закону или иному нормативному правовому акту, имеющим большую юридическую силу, и нарушают их права и законные интересы.\n\n2. Прокурор, а также государственные органы, органы местного самоуправления, иные органы вправе обратиться в Суд по интеллектуальным правам в случаях, предусмотренных настоящим Кодексом, с заявлениями о признании нормативных правовых актов недействующими, если полагают, что такой оспариваемый акт или отдельные его положения не соответствуют закону или иному нормативному правовому акту, имеющим большую юридическую силу, и нарушают права и законные интересы граждан, организаций, иных лиц.\n\n3. Обращение заинтересованного лица в вышестоящий в порядке подчиненности орган или к должностному лицу не является обязательным условием для подачи заявления в Суд по интеллектуальным правам, если федеральным законом не установлено иное.\n\n(Статья в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 192. Право на обращение в Суд по интеллектуальным правам с заявлением о признании нормативного правового акта недействующим","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"483fa622213eb5737276eff51cf0aac822d917e69c0994e0d15b22711cb3183a"},{"code_id":"APK_RF","article_number":"193","version_date":"2002-07-24","article_text":"1. Заявление о признании нормативного правового акта недействующим должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2, частью 3 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) наименование федерального органа исполнительной власти, принявшего оспариваемый нормативный правовой акт;\n\n2) название, номер, дата принятия, источник опубликования и иные данные об оспариваемом нормативном правовом акте;\n\n3) права и законные интересы заявителя, которые, по его мнению, нарушаются оспариваемым актом или его отдельными положениями;\n\n4) название нормативного правового акта, который имеет большую юридическую силу и на соответствие которому надлежит проверить оспариваемый акт или его отдельные положения;\n\n5) требование заявителя о признании оспариваемого акта недействующим;\n\n6) перечень прилагаемых документов.\n\n2. К заявлению прилагаются документы, указанные в пунктах 1 - 5 статьи 126 настоящего Кодекса, а также текст оспариваемого нормативного правового акта.\n\n3. Подача заявления в Суд по интеллектуальным правам не приостанавливает действие оспариваемого нормативного правового акта.\n\n(Статья в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 193. Требования к заявлению о признании нормативного правового акта недействующим","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7cc50ad35cce141285de99e02f58871340c6678d665c533539a7e9d672f3cd85"},{"code_id":"APK_RF","article_number":"194","version_date":"2002-07-24","article_text":"1. Дело об оспаривании нормативного правового акта рассматривается коллегиальным составом судей в срок, не превышающий трех месяцев со дня поступления заявления в суд, включая срок на подготовку дела к судебному разбирательству и принятие решения по делу.\n\n2. Суд по интеллектуальным правам извещает о времени и месте судебного заседания заявителя, орган, принявший оспариваемый нормативный правовой акт, а также иных заинтересованных лиц. Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения дела, если суд не признал их явку обязательной.\n\n3. Суд по интеллектуальным правам может признать обязательной явку в судебное заседание представителей государственных органов, органов местного самоуправления, иных органов, должностных лиц, принявших оспариваемый нормативный правовой акт, и вызвать их в судебное заседание для дачи объяснений.\n\nНеявка указанных лиц, вызванных в судебное заседание, является основанием для наложения штрафа в порядке и в размерах, которые установлены в главе 11 настоящего Кодекса.\n\n4. При рассмотрении дел об оспаривании нормативных правовых актов Суд по интеллектуальным правам в судебном заседании осуществляет проверку оспариваемого акта или его отдельного положения, устанавливает соответствие его федеральному конституционному закону, федеральному закону и иному нормативному правовому акту, имеющим большую юридическую силу, а также полномочия органа или лица, принявших оспариваемый нормативный правовой акт.\n\n5. Суд по интеллектуальным правам не связан доводами, содержащимися в заявлении об оспаривании нормативного правового акта, и проверяет оспариваемое положение в полном объеме.\n\n6. Обязанность доказывания соответствия оспариваемого нормативного правового акта федеральному конституционному закону, федеральному закону и иному нормативному правовому акту, имеющим большую юридическую силу, наличия у органа или должностного лица надлежащих полномочий на принятие оспариваемого акта, а также обстоятельств, послуживших основанием для его принятия, возлагается на орган, должностное лицо, которые приняли оспариваемый акт.\n\n7. В случае, если имеется вступившее в законную силу решение арбитражного суда или суда общей юрисдикции по ранее рассмотренному делу, проверившего по тем же основаниям соответствие оспариваемого нормативного правового акта иному нормативному правовому акту, имеющему большую юридическую силу, Суд по интеллектуальным правам прекращает производство по делу.\n\n8. Отказ заинтересованного лица, обратившегося в Суд по интеллектуальным правам с заявлением об оспаривании нормативного правового акта, от своего требования, признание требования органом или лицом, которые приняли оспариваемый акт, не препятствуют рассмотрению Судом по интеллектуальным правам дела по существу.\n\n(Статья в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 194. Судебное разбирательство по делу об оспаривании нормативного правового акта","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1cc04cb32b81b37b5fc3e09f490364d752d48d15e19519852e1cc9aa37afc7bd"},{"code_id":"APK_RF","article_number":"195","version_date":"2002-07-24","article_text":"1. Решение по делу об оспаривании нормативного правового акта принимается Судом по интеллектуальным правам по правилам, установленным в главе 20 настоящего Кодекса.\n\n2. По результатам рассмотрения дела об оспаривании нормативного правового акта Суд по интеллектуальным правам принимает одно из решений:\n\n1) о признании оспариваемого акта или отдельных его положений соответствующими иному нормативному правовому акту, имеющему большую юридическую силу;\n\n2) о признании оспариваемого нормативного правового акта или отдельных его положений не соответствующими иному нормативному правовому акту, имеющему большую юридическую силу, и не действующими полностью или в части.\n\n3. В резолютивной части решения по делу об оспаривании нормативного правового акта должны содержаться:\n\n1) наименование органа или лица, принявших оспариваемый акт, его название, номер, дата принятия акта;\n\n2) название нормативного правового акта, который имеет большую юридическую силу и на соответствие которому проверен оспариваемый акт;\n\n3) указание на признание оспариваемого акта соответствующим нормативному правовому акту, имеющему большую юридическую силу, и на отказ в удовлетворении заявленного требования или на признание оспариваемого акта не соответствующим нормативному правовому акту, имеющему большую юридическую силу, и не действующим полностью или в части.\n\n4. Решение Суда по интеллектуальным правам по делу об оспаривании нормативного правового акта вступает в законную силу немедленно после его принятия.\n\n5. Нормативный правовой акт или отдельные его положения, признанные Судом по интеллектуальным правам недействующими, не подлежат применению с момента вступления в законную силу решения суда и должны быть приведены органом или лицом, принявшими оспариваемый акт, в соответствие с законом или иным нормативным правовым актом, имеющими большую юридическую силу.\n\n6. Копии решения Суда по интеллектуальным правам в срок, не превышающий десяти дней со дня его принятия, направляются лицам, участвующим в деле.\n\n7. Вступившее в законную силу решение Суда по интеллектуальным правам по делу об оспаривании нормативного правового акта может быть обжаловано по правилам, установленным настоящим Кодексом.\n\n(Статья в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 195. Решение суда по делу об оспаривании нормативного правового акта","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a27c2010e227629bce6a42ac11885fcdc7e9a05549cb3906f4eef79c3e911d18"},{"code_id":"APK_RF","article_number":"195.1","version_date":"2002-07-24","article_text":"1. Дела об оспаривании актов федеральных органов исполнительной власти в сфере патентных прав и прав на селекционные достижения, права на топологии интегральных микросхем, права на секреты производства (ноу-хау), права на средства индивидуализации юридических лиц, товаров, работ, услуг и предприятий, права использования результатов интеллектуальной деятельности в составе единой технологии, содержащих разъяснения законодательства и обладающих нормативными свойствами (далее - акты, обладающие нормативными свойствами), рассматриваются Судом по интеллектуальным правам по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными настоящей главой и определенными в настоящей статье.\n\n2. С заявлением о признании недействующим акта, обладающего нормативными свойствами, вправе обратиться лица, указанные в частях 1 и 2 статьи 192 настоящего Кодекса, если они полагают, что такой акт обладает нормативными свойствами и по своему содержанию не соответствует разъясняемым им нормативным положениям.\n\n3. При рассмотрении дел об оспаривании актов, обладающих нормативными свойствами, Суд по интеллектуальным правам устанавливает, обладает ли оспариваемый акт нормативными свойствами, позволяющими применить его неоднократно в качестве общеобязательного предписания в отношении неопределенного круга лиц, и соответствуют ли положения оспариваемого акта разъясняемым им нормативным положениям.\n\n4. Обязанность доказывания соответствия положений оспариваемого акта разъясняемым им нормативным положениям возлагается на орган или должностное лицо, которые приняли оспариваемый акт.\n\n5. По результатам рассмотрения дела об оспаривании акта, обладающего нормативными свойствами, Суд по интеллектуальным правам принимает одно из следующих решений:\n\n1) о признании оспариваемого акта полностью или в части не обладающим нормативными свойствами и соответствующим разъясняемым им нормативным положениям;\n\n2) о признании оспариваемого акта полностью или в части не соответствующим разъясняемым им нормативным положениям, устанавливающим не предусмотренные разъясняемыми нормативными положениями общеобязательные правила, распространяющиеся на неопределенный круг лиц и рассчитанные на неоднократное применение, и о признании этого акта не действующим полностью или в части.\n\n(Дополнение статьей - Федеральный закон от 15.02.2016 № 18-ФЗ)","article_title":"Статья 195.1. Рассмотрение дел об оспаривании актов, содержащих разъяснения законодательства и обладающих нормативными свойствами","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"42a2849010371b85a3336a2581f1dcea7b44a80d6ab8a3617795c120d6d1a116"},{"code_id":"APK_RF","article_number":"196","version_date":"2002-07-24","article_text":"Вступившее в законную силу решение Суда по интеллектуальным правам по делу об оспаривании нормативного правового акта или по делу об оспаривании акта, обладающего нормативными свойствами, направляется Судом по интеллектуальным правам в официальные издания федеральных органов исполнительной власти и другие официальные издания, в которых был опубликован оспариваемый акт, и подлежит незамедлительному опубликованию указанными изданиями. (В редакции Федерального закона от 17.04.2017 № 76-ФЗ)\n\n(Статья в редакции Федеральный закон от 15.02.2016 № 18-ФЗ)\n\n(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 196. Опубликование решения Суда по интеллектуальным правам по делу об оспаривании нормативного правового акта или по делу об оспаривании акта, обладающего нормативными свойствами","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f136508057e4c0878798285a248fc7e2cfb0ff57a8232b8fbab00b3e91ed397d"},{"code_id":"APK_RF","article_number":"197","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 197. Порядок рассмотрения дел об оспаривании ненормативных правовых актов, решений и действий (бездействия) государственных органов, органов местного самоуправления, иных органов, организаций, наделенных федеральным законом отдельными государственными или иными публичными полномочиями, должностных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a953dd3cf2bc708c849f1f130426d87a16b81bc88b6c9cc7eb7e1e395c35c60"},{"code_id":"APK_RF","article_number":"199","version_date":"2002-07-24","article_text":"1. Заявление о признании ненормативного правового акта недействительным, решений и действий (бездействия) незаконными должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2, частью 3 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) наименование органа или лица, которые приняли оспариваемый акт, решение, совершили оспариваемые действия (бездействие);\n\n2) название, номер, дата принятия оспариваемого акта, решения, время совершения действий;\n\n3) права и законные интересы, которые, по мнению заявителя, нарушаются оспариваемым актом, решением и действием (бездействием);\n\n4) законы и иные нормативные правовые акты, которым, по мнению заявителя, не соответствуют оспариваемый акт, решение и действие (бездействие);\n\n5) требование заявителя о признании ненормативного правового акта недействительным, решений и действий (бездействия) незаконными.\n\nВ заявлении об оспаривании решений и действий (бездействия) должностного лица службы судебных приставов должны быть также указаны сведения об исполнительном документе, в связи с исполнением которого оспариваются решения и действия (бездействие) указанного должностного лица. (В редакции Федерального закона от 02.10.2007 № 225-ФЗ)\n\n2. К заявлению прилагаются документы, указанные в статье 126 настоящего Кодекса, а также текст оспариваемого акта, решения.\n\nК заявлению об оспаривании решений и действий (бездействия) должностного лица службы судебных приставов прилагаются, кроме того, уведомление о вручении или иные документы, подтверждающие направление копии заявления и необходимых доказательств указанному должностному лицу и другой стороне исполнительного производства. (В редакции Федерального закона от 02.10.2007 № 225-ФЗ)","article_title":"Статья 199. Требования к заявлению о признании ненормативного правового акта недействительным, решений и действий (бездействия) незаконными","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a32e1b7c3b06dc7b35203d0664d109d68b20b79bd4407290dc454863116f94e"},{"code_id":"APK_RF","article_number":"2","version_date":"2002-07-24","article_text":"Задачами судопроизводства в арбитражных судах являются:\n\n1) защита нарушенных или оспариваемых прав и законных интересов лиц, осуществляющих предпринимательскую и иную экономическую деятельность, а также прав и законных интересов Российской Федерации, субъектов Российской Федерации, муниципальных образований в сфере предпринимательской и иной экономической деятельности, органов государственной власти Российской Федерации, органов государственной власти субъектов Российской Федерации, органов местного самоуправления, иных органов, должностных лиц в указанной сфере;\n\n2) обеспечение доступности правосудия в сфере предпринимательской и иной экономической деятельности;\n\n3) справедливое публичное судебное разбирательство в разумный срок независимым и беспристрастным судом; (В редакции Федерального закона от 30.04.2010 № 69-ФЗ)\n\n4) укрепление законности и предупреждение правонарушений в сфере предпринимательской и иной экономической деятельности;\n\n5) формирование уважительного отношения к закону и суду;\n\n6) содействие становлению и развитию партнерских деловых отношений, мирному урегулированию споров, формированию обычаев и этики делового оборота. (В редакции Федерального закона от 26.07.2019 № 197-ФЗ)","article_title":"Статья 2. Задачи судопроизводства в арбитражных судах","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8cd701b4b761ab88947dbd7ddf5ffd63c0b0efb1f8f4d09d4bdb154c429c4093"},{"code_id":"APK_RF","article_number":"20","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\n1. Вопросы, возникающие при рассмотрении дела судом в коллегиальном составе, разрешаются судьями большинством голосов. Никто из судей не вправе воздержаться от голосования. Судья - председательствующий в заседании - голосует последним.\n\n2. Судья, несогласный с мнением большинства судей, голосовавших за принятие судебного акта, обязан подписать этот судебный акт и вправе изложить в письменной форме свое особое мнение.\n\nСудья, голосовавший за принятый судебный акт по существу рассматриваемого судом вопроса, но оставшийся в меньшинстве при голосовании по какому-либо другому вопросу или по мотивировке принятого судебного акта, также вправе изложить в письменной форме свое особое мнение.\n\nПри изложении своего особого мнения судья не вправе сообщать кому бы то ни было сведения о содержании обсуждения при принятии судебного акта, о позиции отдельных судей, входивших в состав суда, и иным способом раскрывать тайну совещания судей.\n\nОсобое мнение судьи должно быть изготовлено в срок, не превышающий пяти дней со дня принятия решения по делу. Особое мнение судьи приобщается к материалам дела, но не оглашается.\n\n(Часть в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 20. Порядок разрешения вопросов судом в коллегиальном составе. Особое мнение судьи","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e2b2cf4ecf2d39148857eab4330d6e8e0f1aa55b414be24eed3dc7575a5b3e78"},{"code_id":"APK_RF","article_number":"200","version_date":"2002-07-24","article_text":"ений и действий (бездействия) органов, осуществляющих публичные полномочия, должностных лиц\n\n(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\nДела об оспаривании решений и действий (бездействия) должностного лица службы судебных приставов рассматриваются в срок, не превышающий десяти дней со дня поступления заявления в арбитражный суд, включая срок на подготовку дела к судебному разбирательству и принятие решения по делу. Указанный срок может быть продлен на основании мотивированного заявления судьи, рассматривающего дело, председателем арбитражного суда, заместителем председателя арбитражного суда до трех месяцев в связи с особой сложностью дела, со значительным числом участников арбитражного процесса. (В редакции  федеральных законов от 02.10.2007 № 225-ФЗ, от 25.12.2023 № 667-ФЗ)\n\nДела об оспаривании решений органов местного самоуправления о сносе самовольных построек или об их приведении в соответствие с предельными параметрами разрешенного строительства, реконструкции объектов капитального строительства, установленными правилами землепользования и застройки, документацией по планировке территории, или обязательными требованиями к параметрам объектов капитального строительства, установленными федеральными законами, об оспаривании решений органов государственной власти или органов местного самоуправления о прекращении вещных прав на земельные участки (права пожизненного наследуемого владения, права постоянного (бессрочного) пользования) в связи с неисполнением обязанностей по сносу самовольной постройки или ее приведению в соответствие с указанными параметрами и требованиями рассматриваются в срок, не превышающий одного месяца со дня поступления соответствующего заявления в арбитражный суд, включая срок на подготовку дела к судебному разбирательству и принятие решения по делу. (Дополнение абзацем - Федеральный закон от 03.08.2018 № 340-ФЗ)","article_title":"Статья 200. Судебное разбирательство по делам об оспаривании ненормативных правовых актов, реш","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d3c45c2cd312f4a1038cc4f242b20330ed02323d6cac12d36a1aaadf02566af8"},{"code_id":"APK_RF","article_number":"201","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\n1) наименование органа или лица, принявших оспариваемый акт, решение; название, номер, дата принятия оспариваемого акта, решения;\n\n2) название закона или иного нормативного правового акта, на соответствие которому проверены оспариваемый акт, решение;\n\n3) указание на признание оспариваемого акта недействительным или решения незаконным полностью или в части и обязанность устранить допущенные нарушения прав и законных интересов заявителя либо на отказ в удовлетворении требования заявителя полностью или в части.\n\n1) наименование органа или лица, совершивших оспариваемые действия (бездействие) и отказавших в совершении действий, принятии решений; сведения о действиях (бездействии), решениях;\n\n2) название закона или иного нормативного правового акта, на соответствие которым проверены оспариваемые действия (бездействие), решения;\n\n3) указание на признание оспариваемых действий (бездействия) незаконными и обязанность соответствующих органов, осуществляющих публичные полномочия, должностных лиц совершить определенные действия, принять решения или иным образом устранить допущенные нарушения прав и законных интересов заявителя в установленный судом срок либо на отказ в удовлетворении требования заявителя полностью или в части. (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 201. Решение арбитражного суда по делу об оспаривании ненормативных правовых актов, решений и действий (бездействия) органов, осуществляющих публичные полномочия, должностных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"11651f5cc994222911bdacd0b4bebbd26dd6f876e94248a710386b0ff4f41efc"},{"code_id":"APK_RF","article_number":"203","version_date":"2002-07-24","article_text":"Заявление о привлечении к административной ответственности подается в арбитражный суд по адресу или месту жительства лица, в отношении которого составлен протокол об административном правонарушении. В случае, если лицо, в отношении которого составлен протокол об административном правонарушении, привлекается за административное правонарушение, совершенное вне места его нахождения или места его жительства, указанное заявление может быть подано в арбитражный суд по месту совершения административного правонарушения. (В редакции федеральных законов от 27.07.2010 № 228-ФЗ, от 28.11.2018 № 451-ФЗ)","article_title":"Статья 203. Подача заявления о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a486ec659e8421069a617f23fb46ecb6af1dfc37863e94316c25a20b101409dd"},{"code_id":"APK_RF","article_number":"204","version_date":"2002-07-24","article_text":"1. Заявление о привлечении к административной ответственности лиц, осуществляющих предпринимательскую и иную экономическую деятельность, должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2, частью 3 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) дата и место совершения действий, послуживших основанием для составления протокола об административном правонарушении;\n\n2) должность, фамилия и инициалы лица, составившего протокол об административном правонарушении;\n\n3) сведения о лице, в отношении которого составлен протокол об административном правонарушении;\n\n4) нормы закона, предусматривающего административную ответственность за действия, послужившие основанием для составления протокола об административном правонарушении;\n\n5) требование заявителя о привлечении к административной ответственности.\n\n2. К заявлению прилагаются протокол об административном правонарушении и прилагаемые к протоколу документы, а также уведомление о вручении или иной документ, подтверждающие направление копии заявления лицу, в отношении которого составлен протокол об административном правонарушении.","article_title":"Статья 204. Требования к заявлению о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7802377a1009ddfab7e239273537adbe6cf9b4b191057b0bcc5ff234120a1833"},{"code_id":"APK_RF","article_number":"205","version_date":"2002-07-24","article_text":"В случае непредставления административным органом, составившим протокол, доказательств, необходимых для рассмотрения дела и принятия решения, арбитражный суд может истребовать доказательства от указанного органа по своей инициативе.","article_title":"Статья 205. Судебное разбирательство по делам о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1f8e044d3d4b236973a8fbe4cfd6f5b0d6e68f38c43390102b205759fe206a6c"},{"code_id":"APK_RF","article_number":"206","version_date":"2002-07-24","article_text":"1. Решение по делу о привлечении к административной ответственности принимается арбитражным судом по правилам, установленным в главе 20 настоящего Кодекса.\n\n2. По результатам рассмотрения заявления о привлечении к административной ответственности арбитражный суд принимает решение о привлечении к административной ответственности или об отказе в удовлетворении требования административного органа о привлечении к административной ответственности.\n\n3. В резолютивной части решения о привлечении к административной ответственности должны содержаться:\n\n1) наименование лица, привлеченного к административной ответственности, его адрес или место жительства, сведения о его государственной регистрации в качестве юридического лица или индивидуального предпринимателя; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) нормы закона, на основании которых данное лицо привлекается к административной ответственности;\n\n3) вид административного наказания и санкции, возложенные на лицо, привлеченное к административной ответственности.\n\n4. Решение по делу о привлечении к административной ответственности вступает в законную силу по истечении десяти дней со дня его принятия, если не подана апелляционная жалоба.\n\nВ случае подачи апелляционной жалобы решение, если оно не изменено или не отменено, вступает в законную силу со дня принятия постановления арбитражным судом апелляционной инстанции.\n\nВ других случаях решения по делам о привлечении к административной ответственности обжалуются в порядке, установленном статьей 181 настоящего Кодекса.\n\nАбзац. (Дополнение абзацем - Федеральный закон от 28.06.2014 № 186-ФЗ) (Утратил силу - Федеральный закон от 22.11.2016 № 393-ФЗ)\n\n(Дополнение частью - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\n5. Копия решения арбитражного суда по делу о привлечении к административной ответственности направляется арбитражным судом в трехдневный срок со дня его принятия лицам, участвующим в деле. Арбитражный суд может направить копию решения также в вышестоящий в порядке подчиненности административный орган.","article_title":"Статья 206. Решение арбитражного суда по делу о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"53740a1e54302582ec750aa8f29176ce58aaccf2905a9a739951f87b71d6daf3"},{"code_id":"APK_RF","article_number":"207","version_date":"2002-07-24","article_text":"1. Дела об оспаривании решений государственных органов, иных органов, должностных лиц, уполномоченных в соответствии с федеральным зак\n\nоном рассматривать дела об административных правонарушениях (далее в параграфе 2 главы 25, пункте 4 части 1 статьи 227 настоящего Кодекса - административные органы), о привлечении к административной ответственности лиц, осуществляющих предпринимательскую и иную экономическую деятельность, рассматриваются арбитражным судом по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными в настоящей главе и федеральном законе об административных правонарушениях. (В редакции Федерального закона от 25.06.2012 № 86-ФЗ)","article_title":"Статья 207. Порядок рассмотрения дел об оспаривании решений административных органов о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b09e913a4ba26ffbfab72dc6d6c860a94a9a9da503114fa830e3d83e0dc1a8c5"},{"code_id":"APK_RF","article_number":"208","version_date":"2002-07-24","article_text":"В случае пропуска указанного срока он может быть восстановлен судом по ходатайству заявителя.","article_title":"Статья 208. Подача заявления об оспаривании решения административного органа о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0cd71292b482af83ef3212cd490f600b286154c53b5f248fcd4aab1a0db238c4"},{"code_id":"APK_RF","article_number":"209","version_date":"2002-07-24","article_text":"1. Заявление об оспаривании решения административного органа о привлечении к административной ответственности должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2, частью 3 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) наименование административного органа, принявшего оспариваемое решение;\n\n2) название, номер, дата принятия оспариваемого решения и иные сведения о нем;\n\n3) права и законные интересы заявителя, которые нарушены, по его мнению, оспариваемым решением;\n\n4) требование заявителя и основания, по которым он оспаривает решение административного органа.\n\n2. К заявлению об оспаривании решения административного органа прилагаются текст оспариваемого решения, а также уведомление о вручении или иной документ, подтверждающие направление копии заявления об оспаривании решения в административный орган, его принявший.","article_title":"Статья 209. Требования к заявлению об оспаривании решения административного органа о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"166cd53dda0bffea7a239f1e15d1756db3fc9641c34d4d9c522aee15735772cd"},{"code_id":"APK_RF","article_number":"21","version_date":"2002-07-24","article_text":"1. Судья не может участвовать в рассмотрении дела и подлежит отводу, если он:\n\n1) при предыдущем рассмотрении данного дела участвовал в нем в качестве судьи и его повторное участие в рассмотрении дела в соответствии с требованиями настоящего Кодекса является недопустимым;\n\n2) при предыдущем рассмотрении данного дела участвовал в нем в качестве прокурора, помощника судьи, секретаря судебного заседания, представителя, эксперта, специалиста, переводчика или свидетеля; (В редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\n3) при предыдущем рассмотрении данного дела участвовал в нем в качестве судьи иностранного суда, третейского суда или арбитража;\n\n31) являлся судебны\n\nм примирителем по данному делу; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n4) является родственником лица, участвующего в деле, или его представителя;\n\n5) лично, прямо или косвенно заинтересован в исходе дела либо имеются иные обстоятельства, которые могут вызвать сомнение в его беспристрастности;\n\n6) находится или ранее находился в служебной или иной зависимости от лица, участвующего в деле, или его представителя;\n\n7) делал публичные заявления или давал оценку по существу рассматриваемого дела.\n\n2. В состав арбитражного суда, рассматривающего дело, не могут входить лица, являющиеся родственниками.","article_title":"Статья 21. Отвод судьи","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1437f3e0ba501003e8e23dafec0bd0b00500b83d35fe186b3a4754bfa5b1c7b2"},{"code_id":"APK_RF","article_number":"211","version_date":"2002-07-24","article_text":"1. Решение по делу об оспаривании решения административного органа о привлечении к административной ответственности принимается арбитражным судом по правилам, установленным в главе 20 настоящего Кодекса.\n\n2. В случае, если при рассмотрении заявления об оспаривании решения административного органа о привлечении к административной ответственности арбитражный суд установит, что оспариваемое решение или порядок его принятия не соответствует закону, либо отсутствуют основания для привлечения к административной ответственности или применения конкретной меры ответственности, либо оспариваемое решение принято органом или должностным лицом с превышением их полномочий, суд принимает решение о признании незаконным и об отмене оспариваемого решения полностью или в части либо об изменении решения.\n\n3. В случае, если при рассмотрении заявления об оспаривании решения административного органа о привлечении к административной ответственности арбитражный суд установит, что решение административного органа о привлечении к административной ответственности является законным и обоснованным, суд принимает решение об отказе в удовлетворении требования заявителя.\n\n4. В резолютивной части решения по делу об оспаривании решения административного органа должны содержаться:\n\n1) название, номер, дата и место принятия, другие необходимые сведения об оспариваемом решении;\n\n2) наименование лица, привлеченного к административной ответственности, его адрес или место жительства, сведения о его государственной регистрации в качестве юридического лица или индивидуального предпринимателя; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) указание на признание решения незаконным и его отмену полностью или в части, либо на отказ в удовлетворении требования заявителя полностью или в части, либо на меру ответственности, если она изменена судом.\n\n5. Решение арбитражного суда вступает в законную силу по истечении десяти дней со дня его принятия, если не подана апелляционная жалоба.\n\nВ случае подачи апелляционной жалобы решение, если оно не изменено или не отменено, вступает в законную силу со дня принятия постановления арбитражным судом апелляционной инстанции.\n\nВ других случаях решения по делам об оспаривании решений административных органов о привлечении к административной ответственности обжалуются в порядке, установленном статьей 181 настоящего Кодекса.\n\nАбзац. (Дополнение абзацем - Федеральный закон от 28.06.2014 № 186-ФЗ) (Утратил силу - Федеральный закон от 22.11.2016 № 393-ФЗ)\n\n(Дополнение частью - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\n6. Копия решения направляется арбитражным судом в трехдневный срок со дня его принятия лицам, участвующим в деле. Арбитражный суд может направить копию решения также в вышестоящий в порядке подчиненности административный орган.","article_title":"Статья 211. Решение арбитражного суда по делу об оспаривании решения административного органа о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"712f5c654f8f005fc466da7036b14717f5717e68b61236d10cc38f583776a40a"},{"code_id":"APK_RF","article_number":"213","version_date":"2002-07-24","article_text":"1. Государственные органы, органы местного самоуправления, иные органы, наделенные в соответствии с федеральным законом контрольными функциями (далее - контрольные органы), вправе обратиться в арбитражный суд с заявлением о взыскании с лиц, осуществляющих предпринимательскую и иную экономическую деятельность, установленных законом обязательных платежей и санкций, если федеральным законом не предусмотрен иной порядок их взыскания.\n\n2. Заявление о взыскании подается в арбитражный суд, если не исполнено требование заявителя об уплате взыскиваемой суммы в добровольном порядке или пропущен указанный в таком требовании срок уплаты.","article_title":"Статья 213. Право на обращение в арбитражный суд с заявлением о взыскании обязательных платежей и санкций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"54b895e11263d6a9d7a2fe50c5d840c8f0cb75d05e9b0cab04039fbd3a1863f8"},{"code_id":"APK_RF","article_number":"214","version_date":"2002-07-24","article_text":"1. Заявление о взыскании обязательных платежей и санкций должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2, частью 3 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) наименование платежа, подлежащего взысканию, размер и расчет его суммы;\n\n2) нормы федерального закона и иного нормативного правового акта, предусматривающие уплату платежа;\n\n3) сведения о направлении требования об уплате платежа в добровольном порядке.\n\n2. К заявлению о взыскании обязательных платежей и санкций прилагаются документы, указанные в пунктах 1 - 5 статьи 126 настоящего Кодекса, а также документ, подтверждающий направление заявителем требования об уплате взыскиваемого платежа в добровольном порядке.","article_title":"Статья 214. Требования к заявлению о взыскании обязательных платежей и санкций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e70557b982a9a9a1011819956338b9d8ed36788da1e0504b1934ed92b9096fd8"},{"code_id":"APK_RF","article_number":"215","version_date":"2002-07-24","article_text":"Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения дела, если суд не признал их явку обязательной.\n\nНеявка указанных лиц, вызванных в судебное заседание, является основанием для наложения штрафа в порядке и в размере, которые установлены в главе 11 настоящего Кодекса.","article_title":"Статья 215. Судебное разбирательство по делам о взыскании обязательных платежей и санкций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a9d23f9828e18c6381a8926a4ea5cce055b2ec434d51878f7d30b66c9c7869c4"},{"code_id":"APK_RF","article_number":"216","version_date":"2002-07-24","article_text":"1. Решение арбитражного суда по делу о взыскании обязательных платежей и санкций принимается по правилам, установленным в главе 20 настоящего Кодекса.\n\n2. При удовлетворении требования о взыскании обязательных платежей и санкций в резолютивной части решения должны быть указаны:\n\n1) наименование лица, обязанного уплатить сумму задолженности, его адрес или место жительства, сведения о его государственной регистрации; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) общий размер подлежащей взысканию денежной суммы с определением отдельно основной задолженности и санкций.\n\nРАЗДЕЛ IV. ОСОБЕННОСТИ ПРОИЗВОДСТВА В АРБИТРАЖНОМ СУДЕ ПО ОТДЕЛЬНЫМ КАТЕГОРИЯМ ДЕЛ","article_title":"Статья 216. Решение арбитражного суда по делу о взыскании обязательных платежей и санкций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93dffa32380988133389c464c7d51e18c6a38133e70bafd71761f11b0bebf139"},{"code_id":"APK_RF","article_number":"217","version_date":"2002-07-24","article_text":"1. Дела об установлении фактов, имеющих юридическое значение, рассматриваются арбитражным судом по общим правилам искового производства, установленным настоящим Кодексом, с особенностями, предусмотренными в настоящей главе.\n\n2. Производство по делам об установлении фактов, имеющих юридическое значение, возбуждается в арбитражном суде на основании заявлений об установлении фактов, имеющих юридическое значение.\n\n3. В случае, если при рассмотрении дела об установлении фактов, имеющих юридическое значение, выясняется, что возник спор о праве, арбитражный суд оставляет заявление об установлении фактов, имеющих юридическое значение, без рассмотрения, о чем выносит определение. В определении заявителю и другим заинтересованным лицам разъясняется их право разрешить спор в порядке искового производства.","article_title":"Статья 217. Порядок рассмотрения дел об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6bbcd99a99ed1fc61ea29d118e26998108205f8a82b58ff8e1202f8c7569b1a"},{"code_id":"APK_RF","article_number":"218","version_date":"2002-07-24","article_text":"1. Арбитражный суд устанавливает факты, имеющие юридическое значение для возникновения, изменения или прекращения прав юридических лиц и индивидуальных предпринимателей в сфере предпринимательской и иной экономической деятельности.\n\n2. Арбитражный суд рассматривает дела об установлении:\n\n1) факта владения и пользования юридическим лицом или индивидуальным предпринимателем недвижимым имуществом как своим собственным;\n\n2) факта государственной регистрации юридического лица или индивидуального предпринимателя в определенное время и в определенном месте;\n\n3) факта принадлежности правоустанавливающего документа, действующего в сфере предпринимательской и иной экономической деятельности, юридическому лицу или индивидуальному предпринимателю, если наименование юридического лица, имя, отчество или фамилия индивидуального предпринимателя, указанные в документе, не совпадают с наименованием юридического лица по его учредительному документу, именем, отчеством или фамилией индивидуального предпринимателя по его паспорту или свидетельству о рождении;\n\n4) других фактов, порождающих юридические последствия в сфере предпринимательской и иной экономической деятельности.","article_title":"Статья 218. Дела об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"146df9a6093d236985e4e16fe13b480ea4c748dd8696b5be85a3c886c9024200"},{"code_id":"APK_RF","article_number":"219","version_date":"2002-07-24","article_text":"1. Юридическое лицо или индивидуальный предприниматель вправе обратиться в арбитражный суд с заявлением об установлении фактов, имеющих юридическое значение, только если у заявителя отсутствует возможность получить или восстановить надлежащие документы, удостоверяющие эти факты, и если федеральным законом или иным нормативным правовым актом не предусмотрен иной внесудебный порядок установления соответствующих фактов.","article_title":"Статья 219. Право на обращение в арбитражный суд с заявлением об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5853c78138c11a470c1ec5d53d04e3e780e1e479918ca49701a8b36942d17560"},{"code_id":"APK_RF","article_number":"22","version_date":"2002-07-24","article_text":"1. Судья, принимавший участие в рассмотрении дела в арбитражном суде первой инстанции, не может участвовать в рассмотрении этого дела в судах апелляционной и кассационной инстанций, а также в порядке надзора.\n\n2. Судья, принимавший участие в рассмотрении дела в арбитражном суде апелляционной инстанции, не может участвовать в рассмотрении этого дела в судах первой и кассационной инстанций, а также в порядке надзора.\n\n3. Судья, принимавший участие в рассмотрении дела в арбитражном суде кассационной инстанции, не может участвовать в рассмотрении этого дела в судах первой и апелляционной инстанций, а также в порядке надзора.\n\n4. Судья, принимавший участие в рассмотрении дела в порядке надзора, не может участвовать в рассмотрении этого дела в судах первой, апелляционной и кассационной инстанций.","article_title":"Статья 22. Недопустимость повторного участия судьи в рассмотрении дела","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8bdae3e6a59a30e16471209d4979aa45bb31a2579e96eb9d79c59b8c9dd77413"},{"code_id":"APK_RF","article_number":"220","version_date":"2002-07-24","article_text":"1. Заявление об установлении фактов, имеющих юридическое значение, должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) факт, об установлении которого ходатайствует заявитель;\n\n2) нормы закона, предусматривающего, что данный факт порождает юридические последствия в сфере предпринимательской и иной экономической деятельности;\n\n3) обоснование необходимости установления данного факта;\n\n4) доказательства, подтверждающие невозможность получения заявителем надлежащих доказательств или восстановления утраченных документов.\n\n2. К заявлению об установлении фактов, имеющих юридическое значение, прилагаются документы, предусмотренные пунктами 2 - 5 статьи 126 настоящего Кодекса.","article_title":"Статья 220. Требования к заявлению об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"98ba3590a50166d901856bfe2bb0b8581e938a9589729c8a5d82a55e478d8fe8"},{"code_id":"APK_RF","article_number":"221","version_date":"2002-07-24","article_text":"1. Дела об установлении фактов, имеющих юридическое значение, рассматриваются судьей единолично в судебном заседании с участием заявителя и других заинтересованных лиц. К их рассмотрению не могут привлекаться арбитражные заседатели.\n\n2. При подготовке дела к су\n\nдебному разбирательству судья определяет круг заинтересованных по делу лиц, права которых может затронуть решение об установлении факта, имеющего юридическое значение, извещает этих лиц о производстве по делу, рассматривает вопрос о привлечении их к участию в деле, извещает о времени и месте судебного заседания.\n\n3. При рассмотрении дела об установлении факта, имеющего юридическое значение, арбитражный суд в судебном заседании проверяет, не предусмотрен ли законом или иным нормативным правовым актом иной внесудебный порядок установления данного факта, имелась ли у заявителя другая возможность получить или восстановить необходимые документы, устанавливает, порождает ли данный факт юридически значимые последствия для заявителя в связи с осуществлением им предпринимательской или иной экономической деятельности, выясняет, не затрагивает ли права других лиц установление требуемого факта, не возник ли спор о праве.\n\n4. В случае, если в ходе судебного разбирательства по делу об установлении факта, имеющего юридическое значение, выяснится, что возник спор о праве, арбитражный суд оставляет заявление об установлении факта, имеющего юридическое значение, без рассмотрения, о чем выносит определение.\n\nВ определении заявителю и другим заинтересованным по делу лицам разъясняется их право разрешить спор в порядке искового производства.","article_title":"Статья 221. Судебное разбирательство по делам об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cf0da91d21bd65ba118de19af4cf1097bbad85c60e1ac7a75dd6e36c14e4033a"},{"code_id":"APK_RF","article_number":"222","version_date":"2002-07-24","article_text":"1. Решение по делу об установлении факта, имеющего юридическое значение, принимается арбитражным судом по правилам, установленным в главе 20 настоящего Кодекса.\n\n2. При удовлетворении судом заявления об установлении факта, имеющего юридическое значение, в резолютивной части решения указывается на наличие факта, имеющего юридическое значение, и излагается установленный факт.\n\n3. Решение арбитражного суда об установлении факта, имеющего юридическое значение, является основанием для регистрации такого факта или оформления прав, которые возникают в связи с установленным фактом, соответствующими органами и не заменяет собой документы, выдаваемые этими органами.\n\n(Дополнение главой - Федеральный закон от 30.04.2010 № 69-ФЗ)","article_title":"Статья 222. Решение арбитражного суда по делу об установлении факта, имеющего юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c20000cda2cbd87e2f8bcd326936f845de37b2924df7c47c7d967829f8da42c8"},{"code_id":"APK_RF","article_number":"222.1","version_date":"2002-07-24","article_text":"1. Лицо, полагающее, что государственным органом, органом местного самоуправления, иным органом, организацией, должностным лицом нарушено его право на судопроизводство в разумный срок или право на исполнение судебного акта в разумный срок, вправе обратиться в арбитражный суд с заявлением о присуждении компенсации.\n\n2. Заявление о присуждении компенсации за нарушение права на судопроизводство в разумный срок может быть подано заинтересованным лицом в течение шести месяцев со дня вступления в законную силу последнего судебного акта, принятого по данному делу.\n\nЗаявление о присуждении компенсации за нарушение права на судопроизводство в разумный срок может быть также подано до окончания производства по делу в случае, если продолжительность рассмотрения дела превышает три года и заинтересованное лицо ранее обращалось с заявлением об ускорении рассмотрения дела в порядке, установленном настоящим Кодексом.\n\n3. Заявление о присуждении компенсации за нарушение права на исполнение судебного акта в разумный срок может быть подано заинтересованным лицом в арбитражный суд до окончания производства по исполнению судебного акта, но не ранее чем через шесть месяцев со дня истечения срока, установленного федеральным законом для исполнения судебного акта, и не позднее чем через шесть месяцев со дня окончания производства по исполнению судебного акта.\n\n4. Заявление о присуждении компенсации за нарушение права на судопроизводство в разумный срок не может рассматриваться судьей, если он ранее принимал участие в рассмотрении дела, в связи с которым возникли основания для подачи такого заявления.","article_title":"Статья 222.1. Право на обращение в арбитражный суд с заявлением о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9b1c3a01906d2dc49c1e2a6367275be1880be168aa97494178dc2b23662150f5"},{"code_id":"APK_RF","article_number":"222.2","version_date":"2002-07-24","article_text":"1. Заявление о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок подается в арбитражный суд, полномочный рассматривать такое заявление, через арбитражный суд, принявший решение.\n\n2. Арбитражный суд, принявший решение, обязан направить заявление о присуждении компенсации, указанной в части 1 настоящей статьи, вместе с делом в соответствующий суд в трехдневный срок со дня поступления такого заявления в арбитражный суд.","article_title":"Статья 222.2. Порядок подачи заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d0f54e9a69d7cac22b79eda47e9fd62dfd135c1140139bfb0bafea439bd88892"},{"code_id":"APK_RF","article_number":"222.3","version_date":"2002-07-24","article_text":"В заявлении о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок должны быть указаны:\n\n1) наименование арбитражного суда, в который подается заявление;\n\n2) наименование лица, подающего заявление, с указанием его процессуального положения, адреса или места жительства, наименования других лиц, участвующих в деле, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) сведения о судебном акте, принятом по делу, предмет спора, наименование арбитражного суда, рассматривавшего дело, сведения об актах и о действиях органа, организации или должностного лица, на которые возложены обязанности по исполнению судебного акта;\n\n4) общая продолжительность судопроизводства по делу, исчисляемая со дня поступления искового заявления или заявления в арбитражный суд первой инстанции до дня принятия последнего судебного акта по делу, или общая продолжительность исполнения судебного акта;\n\n5) обстоятельства, известные лицу, подающему заявление, и повлиявшие на длительность судопроизводства по делу или на длительность исполнения судебного акта;\n\n6) доводы лица, подающего заявление, с указанием оснований для присуждения компенсации и ее размера;\n\n7) последствия нарушения права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок и их значимость для заявителя;\n\n8) реквизиты банковского счета лица, подающего заявление, на который должны быть перечислены средства, подлежащие взысканию;\n\n9) перечень прилагаемых к заявлению документов.","article_title":"Статья 222.3. Требования к заявлению о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3df148aee9ba003ee808e1d6749e380fd6167d6348e418067750e3f1571a728c"},{"code_id":"APK_RF","article_number":"222.4","version_date":"2002-07-24","article_text":"1. Вопрос о принятии заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок к производству арбитражного суда решается судьей единолично в пятидневный срок со дня поступления такого заявления в суд.\n\n2. Арбитражный суд обязан принять к производству заявление о присуждении указанной в части 1 настоящей статьи компенсации, поданное с соблюдением установленных настоящим Кодексом требований к его форме и содержанию.\n\n3. Арбитражный суд выносит определение о принятии заявления о присуждении указанной в части 1 настоящей статьи компенсации к производству, в котором указываются время и место проведения судебного заседания по рассмотрению заявления.\n\n4. Копии определения о принятии заявления о присуждении указанной в части 1 настоящей статьи компенсации направляются заявителю, в орган, организацию или должностному лицу, на которые возложены обязанности по исполнению соответствующего судебного акта в связи с его неисполнением в разумный срок, что явилось основанием для обращения заявителя в суд с требованием о присуждении компенсации, а также другим заинтересованным лицам.","article_title":"Статья 222.4. Принятие заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок к производству арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8983b251e32883894d75bbc8f323d46bcc11fda276bf8781e3b56a0977e9d1d4"},{"code_id":"APK_RF","article_number":"222.5","version_date":"2002-07-24","article_text":"1. Если арбитражный суд при рассмотрении вопроса о принятии к производству заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок установит, что заявление подано с нарушением требований, установленных статьей 2223 настоящего Кодекса, или не уплачена государственная пошлина, суд выносит определение об оставлении заявления без движения.\n\n2. В определении арбитражный суд указывает основание для оставления заявления о присуждении компенсации, указанной в части 1 настоящей статьи, без движения и разумный срок, в течение которого должны быть устранены обстоятельства, послужившие основанием для оставления заявления без движения.\n\n3. Копия определения об оставлении заявления о присуждении компенсации, указанной в части 1 настоящей статьи, без движения направляется лицу, подавшему заявление, не позднее следующего дня после дня вынесения определения.\n\n4. В случае, если обстоятельства, послужившие основанием для оставления заявления о присуждении компенсации, указанной в части 1 настоящей статьи, без движения, будут устранены в срок, установленный определением арбитражного суда, заявление считается поданным в день его первоначального поступления в суд. В других случаях заявление считается неподанным и возвращается с документами в порядке, установленном статьей 2226 настоящего Кодекса.","article_title":"Статья 222.5. Оставление заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок без движения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"62ae40207d79aa6e4925911841254f505df8a56ea0041e52a06a68ede0876976"},{"code_id":"APK_RF","article_number":"222.6","version_date":"2002-07-24","article_text":"1. Арбитражный суд возвращает заявление о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок, если при рассмотрении вопроса о принятии заявления к производству установит, что:\n\n1) заявление подано лицом, не имеющим права на его подачу;\n\n2) заявление подано с нарушением порядка и сроков, которые установлены частью 2 статьи 2221 и частью 1 статьи 2222 настоящего Кодекса. При этом ходатайство о восстановлении пропущенного срока подачи заявления не поступало или в восстановлении пропущенного срока его подачи было отказано;\n\n3) до вынесения определения о принятии заявления к производству арбитражного суда от лица, подавшего такое заявление, поступило ходатайство о его возвращении;\n\n4) не устранены обстоятельства, послужившие основанием для оставления заявления без движения, в срок, установленный определением арбитражного суда;\n\n5) срок судопроизводства по делу или срок исполнения судебного акта с очевидностью свидетельствует об отсутствии нарушения права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок.\n\n2. О возвращении заявления о присуждении компенсации, указанной в части 1 настоящей статьи, арбитражный суд выносит определение.\n\n3. Копия определения о возвращении заявления о присуждении компенсации, указанной в части 1 настоящей статьи, направляется заявителю вместе с заявлением и прилагаемыми к нему документами не позднее следующего дня после дня вынесения определения или по истечении срока, установленного арбитражным судом для устранения обстоятельств, послуживших основанием для оставления заявления без движения.\n\n4. Определение о возвращении заявления о присуждении компенсации, указанной в части 1 настоящей статьи, может быть обжаловано в порядке и в сроки, которые установлены статьей 291 настоящего Кодекса.\n\nВ случае отмены определения заявление считается поданным в день его первоначального поступления в арбитражный суд.\n\n5. Возвращение заявления о присуждении компенсации, указанной в части 1 настоящей статьи, не препятствует повторному обращению заинтересованного лица с заявлением в арбитражный суд в общем порядке после устранения обстоятельств, послуживших основанием для возвращения заявления.","article_title":"Статья 222.6. Возвращение заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9d7ac5ab4a27ae01b3f4e29d6bf0dbb73ed116e3b69544979c452980bb92f75a"},{"code_id":"APK_RF","article_number":"222.7","version_date":"2002-07-24","article_text":"Заявление о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок рассматривается арбитражным судом в двухмесячный срок со дня поступления заявления вместе с делом в суд, включая срок на подготовку дела к судебному разбирательству и на принятие судебного акта.","article_title":"Статья 222.7. Срок рассмотрения заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f447acfb7d3ca0bd4873c37bf3bde7f7c8cca28295b0f30ce07a20b5ba3b8a5"},{"code_id":"APK_RF","article_number":"222.8","version_date":"2002-07-24","article_text":"1. Арбитражный суд рассматривает заявление о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок в судебном заседании коллегиальным составом судей по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными настоящей главой, и в соответствии с Федеральным законом \"О компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок\". Заявитель, орган, организация или должностное лицо, на которые возложены обязанности по исполнению судебного акта в связи с его неисполнением в разумный срок, что явилось основанием для обращения заявителя в суд с требованием о присуждении компенсации, а также другие заинтересованные лица извещаются о времени и месте судебного заседания.\n\n2. При рассмотрении заявления о присуждении компенсации, указанной в части 1 настоящей статьи, арбитражный суд устанавливает факт нарушения права заявителя на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок исходя из доводов, изложенных в заявлении, содержания принятых по делу судебных актов, из материалов дела и с учетом следующих обстоятельств:\n\n1) правовая и фактическая сложность дела;\n\n2) поведение заявителя и других участников арбитражного процесса;\n\n3) достаточность и эффективность действий суда или судьи, осуществляемых в целях своевременного рассмотрения дела;\n\n4) достаточность и эффективность осуществляемых в целях своевременного исполнения судебного акта действий органов, организаций или должностных лиц, на которые возложены обязанности по исполнению судебного акта;\n\n5) общая продолжительность судопроизводства по делу и неисполнения судебного акта.\n\n3. При подготовке дела к судебному разбирательству судья определяет круг заинтересованных лиц, в том числе орган, организацию, должностное лицо, которые не исполнили судебный акт в разумный срок, и устанавливает срок для представления ими объяснений, возражений и (или) доводов относительно заявления о присуждении компенсации, указанной в части 1 настоящей статьи. Орган, организация, должностное лицо обязаны представить объяснения, возражения и (или) доводы в срок, установленный арбитражным судом. Непредставление или несвоевременное представление объяснений, возражений и (или) доводов является основанием для наложения судебного штрафа в порядке и в размере, которые установлены главой 11 настоящего Кодекса.","article_title":"Статья 222.8. Особенности рассмотрения заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"af37f89c274994738ac2957f76c2c29dd93bb38d8de97218ca5d06a7822ca0f1"},{"code_id":"APK_RF","article_number":"222.9","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок арбитражный суд принимает решение, которое должно содержать:\n\n1) наименование арбитражного суда, состав суда, принявшего решение;\n\n2) номер дела, по которому принято решение, дату и место принятия решения;\n\n3) наименование лица, подавшего заявление, и его процессуальное положение;\n\n4) наименование лиц, участвующих в деле, в том числе наименование органа, организации или должностного лица, на которые возложены обязанности по исполнению судебного акта;\n\n5) предмет заявления;\n\n6) фамилии лиц, присутствующих в судебном заседании, с указанием их полномочий;\n\n7) сведения о судебных актах, принятых по делу, предмет спора, наименование арбитражного суда, рассматривавшего дело;\n\n8) доводы, изложенные в заявлении;\n\n9) объяснения лиц, присутствовавших в судебном заседании;\n\n10) общую продолжительность судопроизводства по делу или общую продолжительность исполнения судебного акта;\n\n11) мотивы, по которым присуждается компенсация, или мотивы, по которым было отказано в ее присуждении;\n\n12) указание на присуждение компенсации и ее размер или отказ в присуждении компенсации;\n\n13) указание на действия, которые должны осуществить орган, организация или должностное лицо, на которые возложены обязанности по исполнению судебного акта.\n\n2. В решении арбитражного суда указывается на распределение судебных расходов, понесенных в связи с рассмотрением заявления о присуждении компенсации, указанной в части 1 настоящей статьи.\n\n3. Копии решения арбитражного суда направляются заявителю, в орган, организацию или должностному лицу, на которые возложены обязанности по исполнению судебного акта, в пятидневный срок со дня принятия такого решения.\n\n4. Решение арбитражного суда о присуждении компенсации, указанной в части 1 настоящей статьи, вступает в законную силу немедленно после его принятия, подлежит исполнению в порядке, установленном бюджетным законодательством Российской Федерации, и может быть обжаловано в кассационную инстанцию.","article_title":"Статья 222.9. Решение арбитражного суда по делу о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bdc9beddf534bdc037923005be5ce9f3047297abf49c1805a40df4a0710363ad"},{"code_id":"APK_RF","article_number":"223","version_date":"2002-07-24","article_text":"1. Дела о несостоятельности (банкротстве) рассматриваются арбитражным судом по правилам, предусмотренным настоящим Кодексом, с особенностями, установленными федеральными законами, регулирующими вопросы несостоятельности (банкротства).\n\nАпелляционные жалобы на определения, вынесенные арбитражным судом при рассмотрении дел о несостоятельности (банкротстве), рассматриваются арбитражным судом апелляционной инстанции коллегиальным составом судей. (Дополнение абзацем - Федеральный закон от 28.11.2018 № 451-ФЗ)","article_title":"Статья 223. Порядок рассмотрения дел о несостоятельности (банкротстве)","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d89356373302d60c9f99931d05d4987c1afade552b759cd53c26067a5306a138"},{"code_id":"APK_RF","article_number":"224","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 29.06.2015 № 154-ФЗ)","article_title":"Статья 224. Право на обращение в арбитражный суд по делам о несостоятельности (банкротстве)","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c3d60583ea0025287e3d0b0bb40791bf751e16b915e3ccbb2398fe3e17de705b"},{"code_id":"APK_RF","article_number":"225","version_date":"2002-07-24","article_text":"По делам о несостоятельн\n\nости (банкротстве) может быть заключено мировое соглашение в соответствии с федеральным законом, а также допускаются иные примирительные процедуры, предусмотренные главой 15 настоящего Кодекса и другими федеральными законами, регулирующими вопросы несостоятельности (банкротства).\n\n(Дополнение главой - Федеральный закон от 19.07.2009 № 205-ФЗ)","article_title":"Статья 225. Примирение по делам о несостоятельности (банкротстве)","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a620827e1812368dcb92a8cf124bc7d6a355d9774897d3d88f041418b9ef8e3"},{"code_id":"APK_RF","article_number":"225.1","version_date":"2002-07-24","article_text":"1) споры, связанные с созданием, реорганизацией и ликвидацией юридического лица;\n\n2) споры, связанные с принадлежностью акций, долей в уставном (складочном) капитале хозяйственных обществ и товариществ, паев членов кооперативов, установлением их обременений и реализацией вытекающих из них прав (кроме споров, указанных в иных пунктах настоящей части), в частности споры, вытекающие из договоров купли-продажи акций, долей в уставном (складочном) капитале хозяйственных обществ, партнерств, товариществ, споры, связанные с обращением взыскания на акции и доли в уставном (складочном) капитале хозяйственных обществ, партнерств, товариществ, за исключением споров, вытекающих из деятельности депозитариев, связанной с учетом прав на акции и иные ценные бумаги, споров, возникающих в связи с разделом наследственного имущества или разделом общего имущества супругов, включающего в себя акции, доли в уставном (складочном) капитале хозяйственных обществ и товариществ, паи членов кооперативов;\n\n3) споры по искам учредителей, участников, членов юридического лица (далее - участники юридического лица) о возмещении убытков, причиненных юридическому лицу, признании недействительными сделок, совершенных юридическим лицом, и (или) применении последствий недействительности таких сделок;\n\n4) споры, связанные с назначением или избранием, прекращением, приостановлением полномочий и ответственностью лиц, входящих или входивших в состав органов управления и органов контроля юридического лица, споры, возникающие из гражданских правоотношений между указанными лицами и юридическим лицом в связи с осуществлением, прекращением, приостановлением полномочий указанных лиц, а также споры, вытекающие из соглашений участников юридического лица по поводу управления этим юридическим лицом, включая споры, вытекающие из корпоративных договоров;\n\n5) споры, связанные с эмиссией ценных бумаг, в том числе с оспариванием ненормативных правовых актов, решений и действий (бездействия) государственных органов, органов местного самоуправления, иных органов, должностных лиц, решений органов управления эмитента, с оспариванием сделок, совершенных в процессе размещения эмиссионных ценных бумаг, отчетов (уведомлений) об итогах выпуска (дополнительного выпуска) эмиссионных ценных бумаг;\n\n6) споры, вытекающие из деятельности держателей реестра владельцев ценных бумаг, связанной с учетом прав на акции и иные ценные бумаги, с осуществлением держателем реестра владельцев ценных бумаг иных прав и обязанностей, предусмотренных федеральным законом в связи с размещением и (или) обращением ценных бумаг;\n\n7) споры о созыве общего собрания участников юридического лица;\n\n8) споры об обжаловании решений органов управления юридического лица;\n\n9) споры, вытекающие из деятельности нотариусов по удостоверению сделок с долями в уставном капитале обществ с ограниченной ответственностью.\n\n1) споров, предусмотренных пунктами 7 и 9 части 1 настоящей статьи;\n\n2) споров, связанных с оспариванием ненормативных правовых актов, решений и действий (бездействия) государственных органов, органов местного самоуправления, иных органов, организаций, наделенных федеральным законом отдельными государственными или иными публичными полномочиями, должностных лиц;\n\n3) споров, предусмотренных частью 1 настоящей статьи, если на момент возбуждения дела в арбитражном суде или начала третейского разбирательства в третейском суде юридическим лицом, в отношении которого возникли такие споры, является хозяйственное общество, имеющее существенное значение для обеспечения обороны страны и безопасности государства в соответствии с Федеральным законом от 29 апреля 2008 года № 57-ФЗ \"О порядке осуществления иностранных инвестиций в хозяйственные общества, имеющие стратегическое значение для обеспечения обороны страны и безопасности государства\". Настоящий пункт не применяется к спорам, связанным с принадлежностью акций, долей в уставном (складочном) капитале юридических лиц, имеющих существенное значение для обеспечения обороны страны и безопасности государства в соответствии с указанным Федеральным законом, за исключением случаев, если такие споры вытекают из сделок с акциями, долями в уставном (складочном) капитале этих юридических лиц, подлежащих предварительному согласованию в соответствии с указанным Федеральным законом;\n\n4) споров, связанных с применением положений глав IX и XI1 Федерального закона от 26 декабря 1995 года № 208-ФЗ \"Об акционерных обществах\";\n\n5) споров, связанных с исключением участников юридических лиц, указанных в части 1 настоящей статьи.\n\n(Статья в редакции Федерального закона от 29.12.2015 № 409-ФЗ)","article_title":"Статья 225.1. Дела по корпоративным спорам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5eacb913e21a1f8a6f288cfea485e446aeba4ae655baeff7248c6b8b18b6d75e"},{"code_id":"APK_RF","article_number":"225.10","version_date":"2002-07-24","article_text":"1. Гражданин или организация вправе обратиться в арбитражный суд в защиту прав и законных интересов группы лиц при наличии совокупности следующих условий:\n\n1) имеется общий по отношению к каждому члену группы лиц ответчик;\n\n2) предметом спора являются общие либо однородные права и законные интересы членов группы лиц;\n\n3) в основании прав членов группы лиц и обязанностей ответчика лежат схожие фактические обстоятельства;\n\n4) использование всеми членами группы лиц одинакового способа защиты своих прав.\n\n2. Под членами группы лиц в настоящей главе понимаются граждане и организации, отвечающие совокупности условий, указанных в части 1 настоящей статьи, независимо от присоединения их к требованию о защите прав и законных интересов группы лиц.\n\n3. В защиту прав и законных интересов группы лиц могут обратиться гражданин и организация, являющиеся членами этой группы лиц.\n\n4. В установленных федеральными законами случаях в защиту прав и законных интересов группы лиц также могут обратиться орган, организация и гражданин, не являющиеся членами этой группы лиц.\n\n5. Рассмотрение дела о защите прав и законных интересов группы лиц по правилам, установленным настоящей главой, допускается в случае, если ко дню обращения в арбитражный суд лиц, указанных в частях 3 и 4 настоящей статьи, к требованию о защите прав и законных интересов группы лиц присоединились не менее пяти лиц - членов группы лиц.\n\n(Статья в редакции Федерального закона от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.10. Право на обращение в арбитражный суд в защиту прав и законных интересов группы лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8c36be8df735e648ea76deb51a4fa2c3f45ea446b3cbbc5c9bacd93c05052636"},{"code_id":"APK_RF","article_number":"225.10-1","version_date":"2002-07-24","article_text":"1. В исковом заявлении, заявлении, поданных в защиту прав и законных интересов группы лиц, должно быть указано лицо, которому поручено ведение соответствующего дела в интересах группы лиц и которое должно быть членом данной группы лиц, за исключением случаев, предусмотренных частью 4 статьи 22510 настоящего Кодекса (далее в настоящей главе - лицо, которое ведет дело в интересах группы лиц). Лицо, которое ведет дело в интересах группы лиц, действует от имени группы лиц без доверенности на основании указанных в части 6 статьи 22510 настоящего Кодекса заявлений о присоединении к требованию о защите прав и законных интересов группы лиц.\n\n2. Если иное не предусмотрено соглашением группы лиц (статья 22516-1 настоящего Кодекса), лицо, которое ведет дело в интересах группы лиц, пользуется всеми процессуальными правами и несет процессуальные обязанности истца, в том числе обязанность по уплате судебных расходов. Такое лицо обязано добросовестно защищать права и законные интересы группы лиц. Если иное не предусмотрено соглашением группы лиц, лицо, которое ведет дело в интересах группы лиц, вправе поручить ведение дела представителю.\n\n3. Арбитражный суд вправе наложить судебный штраф на лицо, которое ведет дело в интересах группы лиц, в случае злоупотребления им своими процессуальными правами или в случае невыполнения им своих процессуальных обязанностей, в том числе в случае, если это лицо поручило ведение дела представителю.\n\n4. Полномочия лица, которое ведет дело в интересах группы лиц, прекращаются арбитражным судом:\n\n1) в случае отказа лица, которое ведет дело в интересах группы лиц, от иска;\n\n2) по требованию большинства лиц, присоединившихся к требованию о защите прав и законных интересов группы лиц, в случае обнаружения неспособности лица, которое ведет дело в интересах группы лиц, к ведению дела, в том числе в случае длительного отсутствия ввиду болезни, отпуска, в случае пребывания на учебе или нахождения в служебной командировке, либо при наличии обоснованных сомнений в ведении им дела разумно и добросовестно в интересах группы лиц.\n\n(Дополнение статьей - Федеральный закон от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.10-1. Ведение дел о защите прав и законных интересов группы лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da2aea712a834e452b3ccce44c48aae6555e949ecc59535d143e65bdbc0141e6"},{"code_id":"APK_RF","article_number":"225.10-2","version_date":"2002-07-24","article_text":"1. Лицо, присоединившееся к требованию о защите прав и законных интересов группы лиц, имеет право:\n\n1) знакомиться с материалами дела, делать выписки из них, снимать копии;\n\n2) ходатайствовать в арбитражном суде о замене лица, которое ведет дело в интересах группы лиц, в том числе после принятия судебного акта, которым заканчивается рассмотрение дела по существу;\n\n3) присутствовать в судебном заседании, в том числе если оно объявлено закрытым;\n\n4) отказаться от поданного им заявления о присоединении к требованию о защите прав и законных интересов группы лиц.\n\n2. Члены группы лиц, несогласные с предъявленным требованием о защите прав и законных интересов группы лиц, вправе вступить в дело в качестве третьих лиц, не заявляющих самостоятельных требований относительно предмета спора.\n\n(Дополнение статьей - Федеральный закон от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.10-2. Права лица, присоединившегося к требованию о защите прав и законных интересов группы лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"471b474381fa43ff6ad20e9d8ceb3cc75738ebba2e6fdc98d1267664abb00731"},{"code_id":"APK_RF","article_number":"225.11","version_date":"2002-07-24","article_text":"(Статья утратила силу - Федеральный закон от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.11. .","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d24801378a77c2e050518c898cc9003bce6b71cd2cf7b8cadb27f5080cda4b49"},{"code_id":"APK_RF","article_number":"225.12","version_date":"2002-07-24","article_text":"(Статья утратила силу - Федеральный закон от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.12. .","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d24801378a77c2e050518c898cc9003bce6b71cd2cf7b8cadb27f5080cda4b49"},{"code_id":"APK_RF","article_number":"225.13","version_date":"2002-07-24","article_text":"1. Исковое заявление, заявление, подаваемые в защиту прав и законных интересов группы лиц, должны соответствовать требованиям, предусмотренным статьей 125 настоящего Кодекса, а также иным требованиям к форме и содержанию искового заявления, заявления, установленным настоящим Кодексом для отдельных категорий дел. В исковом заявлении, заявлении, подаваемым в защиту прав и законных интересов группы лиц, также указываются:\n\n1) права и законные интересы группы лиц, в защиту которых предъявлено требование о защите прав и законных интересов группы лиц;\n\n2) круг лиц, являющихся членами группы лиц, основания такого членства;\n\n3) наименование лиц, присоединившихся к требованию о защите прав и законных интересов группы лиц, адрес или в случае, если лицом, присоединившимся к требованию о защите прав и законных интересов группы лиц, является гражданин, его место жительства или место пребывания, дата и место его рождения, место его работы или дата и место его государственной регистрации в качестве индивидуального предпринимателя при их наличии.\n\n2. К исковому заявлению, заявлению, подаваемым в защиту прав и законных интересов группы лиц, прилагаются документы, предусмотренные статьей 126 настоящего Кодекса, и иные документы в соответствии с требованиями настоящего Кодекса, установленными к исковому заявлению, заявлению по отдельным категориям дел. К исковому заявлению, заявлению, подаваемым в защиту прав и законных интересов группы лиц, также прилагаются документы, подтверждающие присоединение к требованию о защите прав и законных интересов группы лиц, указанных в пункте 3 части 1 настоящей статьи, и их принадлежность к группе лиц.\n\n3. В исковом заявлении, подаваемом в защиту прав и законных интересов группы лиц органом, организацией или гражданином, которые не являются членами группы лиц, должна содержаться ссылка на федеральный закон, устанавливающий право органа, организации или гражданина, которые не являются членами группы лиц, на обращение в суд в защиту прав и законных интересов группы лиц, а также должно быть указано, в чем конкретно заключаются интересы членов группы лиц, какие их права нарушены.\n\n(Статья в редакции Федерального закона от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.13. Требования к исковому заявлению, заявлению, подаваемым в защиту прав и законных интересов группы лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b8c7c919f2d55112a29e0cd6aca3bb984db204b3a4cd3d419968f89d57dab4d2"},{"code_id":"APK_RF","article_number":"225.14","version_date":"2002-07-24","article_text":"1. При подготовке дела о защите прав и законных интересов группы лиц к судебному разбирательству судья:\n\n1) определяет характер спорного правоотношения и подлежащее применению законодательство;\n\n2) уточняет требования о защите прав и законных интересов группы лиц и основания этих требований;\n\n3) решает вопрос о составе группы лиц и о возможности установления иных лиц, являющихся участниками спорных правоотношений, о привлечении их к участию в деле;\n\n4) предлагает представить доказательства, подтверждающие принадлежность конкретного лица к группе лиц;\n\n5) предлагает лицам, присоединившимся к требованию о защите прав и законных интересов группы лиц, заключить соглашение группы лиц (статья 22516-1 настоящего Кодекса) или присоединиться к ранее заключенному такому соглашению;\n\n6) совершает иные предусмотренные статьей 135 настоящего Кодекса действия.\n\n2. В определении о подготовке дела к судебному разбирательству арбитражный суд устанавливает срок, в течение которого лицо, которое ведет дело в интересах группы лиц, должно предложить другим лицам из этой группы присоединиться к требованию о защите прав и законных интересов группы лиц.\n\n1) наименование ответчика и его адрес;\n\n2) наименование лица, обратившегося в защиту прав и законных интересов группы лиц, и (или) лица, которое ведет дело в интересах группы лиц;\n\n3) требование группы лиц;\n\n4) наименование арбитражного суда, в производстве которого находится дело, номер данного дела;\n\n5) срок, который установлен арбитражным судом и в течение которого иные лица, являющиеся членами группы лиц, могут присоединиться к требованию о защите их прав и законных интересов, рассматриваемому арбитражным судом, путем направления заявления о присоединении к данному требованию лицу, которое ведет дело в интересах группы лиц, и (или) в арбитражный суд;\n\n6) иную определяемую арбитражным судом информацию.\n\n(Статья в редакции Федерального закона от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.14. Подготовка дела о защите прав и законных интересов группы лиц к судебному разбирательству","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f05e201b2bb66c81dea72fcd87a78c04aa9fd7a2d936a97a2da6ee7b37388d9"},{"code_id":"APK_RF","article_number":"225.15","version_date":"2002-07-24","article_text":"1. Замена лица, которое ведет дело в интересах группы лиц, допускается в случае прекращения его полномочий по основаниям, предусмотренным частью 4 статьи 22510-1 настоящего Кодекса.\n\n2. В случае поступления в арбитражный суд заявления лица, которое ведет дело в интересах группы лиц, об отказе от иска арбитражный суд выносит определение об отложении судебного разбирательства и устанавливает срок, который не превышает двух месяцев со дня вынесения определения и в течение которого должна быть произведена замена указанного лица другим лицом.\n\n3. В определении об отложении судебного разбирательства арбитражный суд указывает на обязанность лица, которое ведет дело в интересах группы лиц, уведомить о своем отказе от иска лиц, присоединившихся к требованию о защите прав и законных интересов группы лиц, и определяет форму их уведомления с учетом положений, предусмотренных статьей 22514 настоящего Кодекса. Уведомление также должно содержать указание на необходимость замены лица, которое ведет дело в интересах группы лиц, другим лицом и информацию о последствиях, предусмотренных частью 7 настоящей статьи. Доказательства уведомления об отказе от иска направляются лицом, которое ведет дело в интересах группы лиц, в арбитражный суд.\n\n4. В арбитражный суд в течение срока, установленного в определении арбитражного суда, должны быть представлены доказательства, подтверждающие произведенную замену лица, которое ведет дело в интересах группы лиц.\n\n5. Арбитражный суд не принимает отказ от иска, если на момент истечения срока, установленного в определении суда, не располагает сведениями об уведомлении лиц, присоединившихся к требованию о защите прав и законных интересов группы лиц, и о замене лица, которое ведет дело в интересах группы лиц.\n\n6. О прекращении производства по делу в отношении лица, которое ведет дело в интересах группы лиц, и о замене его другим лицом арбитражный суд выносит определение.\n\n7. В случае, если лицо, которое ведет дело в интересах группы лиц, подавшее заявление об отказе от иска, выполнит все необходимые действия по уведомлению лиц, присоединившихся к требованию о защите прав и законных интересов группы лиц, но указанные лица в течение установленного арбитражным судом срока не произведут замену такого лица другим лицом, арбитражный суд принимает отказ от иска и прекращает производство по делу о защите прав и законных интересов группы лиц в порядке, установленном статьей 151 настоящего Кодекса. Прекращение производства по делу о защите прав и законных интересов группы лиц не лишает лиц из этой группы права обратиться в арбитражный суд за защитой своих нарушенных или оспариваемых прав и законных интересов в порядке, установленном настоящим Кодексом.\n\n8. В случае обращения большинства лиц, присоединившихся к требованию о защите прав и законных интересов группы лиц, с ходатайством о замене лица, которое ведет дело в интересах группы лиц, другим лицом по основанию, предусмотренному пунктом 2 части 4 статьи 22510-1 настоящего Кодекса, в таком обращении должна быть указана кандидатура другого лица. В случае удовлетворения данного ходатайства арбитражный суд заменяет лицо, которое ведет дело в интересах группы лиц, и выносит соответствующее определение.\n\n(Статья в редакции Федерального закона от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.15. Замена лица, которое ведет дело в интересах группы лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"62dc5871250d319cf3c88dd8087cd0999c80be3e408b37ca067c83c2a31f75b9"},{"code_id":"APK_RF","article_number":"225.16","version_date":"2002-07-24","article_text":"1. Дела о защите прав и законных интересов группы лиц рассматриваются арбитражными судами по правилам, установленным настоящим Кодексом, с особенностями, предусмотренными настоящей главой.\n\n2. Дело о защите прав и законных интересов группы лиц рассматривается арбитражным судом в срок, не превышающий восьми месяцев со дня вынесения определения о принятии искового заявления, заявления, поданных в защиту прав и законных интересов группы лиц, к производству арбитражного суда, включая срок на подготовку дела к судебному разбирательству и принятие решения по делу.\n\n3. В случае обращения в арбитражный суд лица, являющегося членом группы лиц, но не присоединившегося к требованию о защите прав и законных интересов данной группы лиц, с самостоятельным иском (далее в настоящей статье - лицо, обратившееся с самостоятельным иском) к тому же ответчику и о том же предмете арбитражный суд разъясняет лицу, обратившемуся с самостоятельным иском, право присоединиться к требованию о защите прав и законных интересов группы лиц в порядке, установленном статьей 22510 настоящего Кодекса.\n\n4. Если лицо, обратившееся с самостоятельным иском, присоединяется к требованию о защите прав и законных интересов группы лиц, ар\n\nбитражный суд выносит определение о присоединении данного лица к требованию о защите прав и законных интересов группы лиц. При этом арбитражный суд, в который обратилось указанное лицо, выносит определение о передаче материалов дела в арбитражный суд, который рассматривает дело о защите прав и законных интересов группы лиц.\n\n5. Если лицо, обратившееся с самостоятельным иском, не воспользуется правом присоединиться к требованию о защите прав и законных интересов группы лиц, арбитражный суд приостанавливает производство по делу указанного лица до вступления в законную силу решения суда по делу о защите прав и законных интересов группы лиц.\n\n6. Производство по делу лица, обратившегося с самостоятельным иском, приостанавливается в том числе в случае, если исковое заявление, заявление, поданные в защиту прав и законных интересов группы лиц, предъявлены позднее обращения в арбитражный суд указанного лица.\n\n7. Арбитражный суд прекращает производство по делу, если установит, что имеется принятое по требованию о защите прав и законных интересов группы лиц и вступившее в законную силу решение арбитражного суда и исковое заявление, заявление поданы лицом, отказавшимся от заявления о присоединении к требованию о защите прав и законных интересов группы лиц либо не воспользовавшимся правом присоединиться к данному требованию или вступить самостоятельно в дело на стороне истца или в качестве третьего лица, заявляющего самостоятельные требования относительно предмета спора, к тому же ответчику и о том же предмете, за исключением случаев, если арбитражный суд признает причины обращения указанного лица с самостоятельными исковым заявлением, заявлением уважительными.\n\n(Статья в редакции Федерального закона от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.16. Порядок рассмотрения дел о защите прав и законных интересов группы лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93b181686363e4f0ad66721849b345032fbed7d8107bbc42be382137216261ae"},{"code_id":"APK_RF","article_number":"225.16-1","version_date":"2002-07-24","article_text":"1. Лицо, которое ведет дело в интересах группы лиц, и лицо (лица), присоединившееся к требованию о защите прав и законных интересов группы лиц, вправе заключить в нотариальной форме соглашение, которое определяет порядок несения его сторонами судебных расходов (соглашение группы лиц). Требования об изменении и о расторжении соглашения группы лиц могут быть предъявлены только в суд, который рассматривает дело о защите прав и законных интересов группы лиц.\n\n2. В случае заключения группой лиц соглашения, указанного в части 1 настоящей статьи, суд после распределения судебных расходов по правилам, установленным главой 9 настоящего Кодекса, решает вопрос об отнесении на лиц, присоединившихся к требованию о защите прав и законных интересов группы лиц, судебных расходов в соответствии с заключенным между ними соглашением либо, если решение по делу о защите прав и законных интересов группы лиц принято в пользу группы лиц, о взыскании судебных расходов в пользу лиц, присоединившихся к требованию о защите прав и законных интересов группы лиц, которые понесли эти расходы в соответствии с условиями такого соглашения.\n\n(Дополнение статьей - Федеральный закон от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.16-1. Порядок несения судебных расходов по делу о защите прав и законных интересов группы лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ec71a821aa4a106a5b53a4425aff7d351491498a812902e2218c2ef7b5d7320f"},{"code_id":"APK_RF","article_number":"225.17","version_date":"2002-07-24","article_text":"1. Решение по делу о защите прав и законных интересов группы лиц принимается по правилам, установленным главой 20 настоящего Кодекса.\n\n2. Обстоятельства, установленные вступившим в законную силу решением арбитражного суда по ранее рассмотренному делу о защите прав и законных интересов группы лиц, не доказываются вновь при рассмотрении арбитражным судом другого дела по заявлению члена этой группы лиц, который ранее не присоединился либо отказался от заявления о присоединении к требованию о защите прав и законных интересов группы лиц, предъявленному к тому же ответчику и о том же предмете, за исключением случаев, если указанные обстоятельства оспариваются этим членом группы лиц.\n\n3. В решении по делу о защите прав и законных интересов группы лиц, принятом в пользу группы лиц, арбитражный суд может указать на обязанность ответчика довести информацию о принятом решении до сведения всех членов группы лиц в установленный арбитражным судом срок через средства массовой информации или иным способом.\n\n4. В резолютивной части решения по делу о защите прав и законных интересов группы лиц должны содержаться выводы в отношении каждого из членов группы, присоединившихся к требованию о защите прав и законных интересов группы лиц.\n\n(Статья в редакции Федерального закона от 18.07.2019 № 191-ФЗ)\n\n(Глава в редакции Федерального закона от 25.06.2012 № 86-ФЗ)","article_title":"Статья 225.17. Решение арбитражного суда по делу о защите прав и законных интересов группы лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aca6ebba0029c553f440891771c3b90507e144558472b3456b47ccc4ab1339a3"},{"code_id":"APK_RF","article_number":"225.2","version_date":"2002-07-24","article_text":"1. Дела по корпоративным спорам рассматриваются арбитражным судом по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными настоящей главой.\n\n2. При рассмотрении дел, предусмотренных пунктом 5 статьи 2251 настоящего Кодекса и связанных с оспариванием ненормативных правовых актов, решений и действий (бездействия) государственных органов, органов местного самоуправления, иных органов, должностных лиц, применяются также особенности, установленные главой 24 настоящего Кодекса.","article_title":"Статья 225.2. Порядок рассмотрения дел по корпоративным спорам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"564690ef6b20c4ec8133a60097b008d3f63f016d6c01a409f15971afe38ce487"},{"code_id":"APK_RF","article_number":"225.3","version_date":"2002-07-24","article_text":"1. Исковое заявление, заявление по корпоративному спору должны соответствовать требованиям, которые предусмотрены статьей 125 настоящего Кодекса. В исковом заявлении, заявлении должны быть также указаны:\n\n1) государственный регистрационный номер юридического лица, указанного в статье 2251 настоящего Кодекса;\n\n2) содержащийся в едином государственном реестре юридических лиц адрес (место нахождения) юридического лица, указанного в статье 2251 настоящего Кодекса.\n\n2. К исковому заявлению, заявлению прилагаются документы, предусмотренные статьей 126 настоящего Кодекса, а также выписка из единого государственного реестра юридических лиц или иной документ, подтверждающий государственную регистрацию юридического лица и содержащий сведения о его адресе (месте нахождения) и государственном регистрационном номере.","article_title":"Статья 225.3. Требования к исковому заявлению, заявлению по корпоративному спору","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"20bd1671226079b6091bde816d4a6fe263d0953d7e91b0fa5d1455198fe1cb31"},{"code_id":"APK_RF","article_number":"225.5","version_date":"2002-07-24","article_text":"1. Корпоративные споры могут быть урегулированы сторонами по правилам, установленным главой 15 настоящего Кодекса, путем заключения мирового соглашения или использования других примирительных процедур, в том числе при содействии посредника, если иное не установлено федеральным законом.\n\n2. Арбитражный суд не принимает отказ истца от иска, признание иска ответчиком, не утверждает мировое соглашение сторон в случаях, если это противоречит закону либо нарушает права и (или) законные интересы других лиц, в том числе юридического лица, указанного в статье 2251 настоящего Кодекса.","article_title":"Статья 225.5. Примирение сторон корпоративных споров","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"810af13293bcd0c44aba12a627c166f81bffaf638f2a31db0c08bf5b574ae124"},{"code_id":"APK_RF","article_number":"225.6","version_date":"2002-07-24","article_text":"1. Обеспечительные меры по корпоративным спорам принимаются арбитражным судом при наличии оснований, предусмотренных статьей 90 настоящего Кодекса. При этом принятие обеспечительных мер не должно приводить к фактической невозможности осуществлять юридическим лицом, указанным в статье 2251 настоящего Кодекса, деятельность или к существенному затруднению осуществления им деятельности, а также к нарушению этим юридическим лицом законодательства Российской Федерации.\n\n2. Обеспечительные меры по корпоративным спорам принимаются арбитражным судом в порядке, предусмотренном главой 8 настоящего Кодекса, с особенностями, установленными настоящей статьей.\n\n3. Обеспечительными мерами по корпоративным спорам могут быть, в частности:\n\n1) наложение ареста на акции, доли в уставном (складочном) капитале хозяйственных обществ и товариществ, паи членов кооперативов;\n\n2) запрещение ответчику и другим лицам совершать сделки и другие действия в отношении акций, долей в уставном (складочном) капитале хозяйственных обществ и товариществ, паев членов кооперативов;\n\n3) запрещение органам юридического лица принимать решения либо совершать иные действия по вопросам, относящимся к предмету спора или непосредственно с ним связанным;\n\n4) запрещение юридическому лицу, его органам или участникам, а также иным лицам исполнять решения, принятые органами этого юридического лица;\n\n5) запрещение держателю реестра владельцев ценных бумаг и (или) депозитарию осуществлять записи по учету или переходу прав на акции и иные ценные бумаги, а также совершать другие действия в связи с размещением и (или) обращением ценных бумаг.\n\n4. Арбитражным судом могут быть приняты иные обеспечительные меры по корпоративным спорам, в том числе одновременно несколько обеспечительных мер.\n\n5. При предоставлении встречного обеспечения его размер определяется в соответствии с частью 1 статьи 94 настоящего Кодекса.\n\n6. В случае, если требование истца носит неимущественный характер, размер встречного обеспечения определяется арбитражным судом исходя из размера возможных убытков ответчика, причиненных обеспечительными мерами, но для физических лиц не может быть менее чем пятьдесят тысяч рублей, для юридических лиц - сто тысяч рублей.\n\n7. В случае, если при рассмотрении заявления о принятии обеспечительных мер у арбитражного суда возникла необходимость заслушать объяснения лиц, участвующих в деле, и лицо, обратившееся с заявлением об обеспечении иска, не предоставило встречное обеспечение, предусмотренное частью 4 настоящей статьи, судья может назначить рассмотрение заявления об обеспечении иска в судебном заседании, которое должно быть проведено в срок, не превышающий пятнадцати дней со дня поступления такого заявления в арбитражный суд.\n\n8. Арбитражный суд не позднее следующего дня после дня поступления заявления об обеспечении иска в арбитражный суд выносит определение о принятии заявления к производству арбитражного суда, в котором указывает время и место судебного заседания. Такое определение не позднее следующего дня после дня его вынесения направляется лицам, участвующим в деле, в порядке, установленном частью 3 статьи 121 настоящего Кодекса.\n\n9. В определении о принятии заявления об обеспечении иска к производству арбитражный суд также может указать на обязанность лица, обратившегося с заявлением об обеспечении иска, уведомить лиц, участвующих в деле, и юридическое лицо, указанное в статье 2251 настоящего Кодекса, о времени и месте рассмотрения заявления об обеспечении иска.\n\n10. В случае неисполнения обязанности по уведомлению, предусмотренной частью 9 настоящей статьи, на лицо, обратившееся с заявлением об обеспечении иска, арбитражным судом может быть наложен судебный штраф в порядке и в размерах, которые установлены главой 11 настоящего Кодекса. В случае, если с заявлением об обеспечении иска обратилось юридическое лицо, судебный штраф налагается на лицо, осуществляющее функции единоличного исполнительного органа или возглавляющее коллегиальный исполнительный орган этого юридического лица.\n\n11. Арбитражный суд вправе рассмотреть заявление об обеспечении иска в отсутствие лиц, указанных в части 7 настоящей статьи, если к началу судебного заседания располагает сведениями об их уведомлении о времени и месте рассмотрения заявления об обеспечении иска или если лицом, ходатайствующим об обеспечении иска, представлены доказательства того, что им предприняты все зависящие от него необходимые меры по такому уведомлению.","article_title":"Статья 225.6. Обеспечительные меры арбитражного суда по корпоративным спорам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0ea698a843f9df1fd9386913df68bad111882dc9a994a72d81d4f1e6254dabbc"},{"code_id":"APK_RF","article_number":"225.7","version_date":"2002-07-24","article_text":"1. В случаях, предусмотренных федеральным законом, органы юридического лица или его участники вправе обратиться в арбитражный суд с иском о понуждении юридического лица созвать общее собрание участников.\n\n2. Дела о понуждении юридического лица созвать общее собрание участников рассматриваются в срок, не превышающий одного месяца со дня поступления искового заявления в арбитражный суд, включая срок на подготовку дела к судебному разбирательству и принятие решения по делу.\n\n3. Решение арбитражного суда о понуждении юридического лица созвать общее собрание участников подлежит немедленному исполнению, если иные сроки не установлены в решении суда.\n\n4. Решение арбитражного суда о пону\n\nждении юридического лица созвать общее собрание участников может быть обжаловано в арбитражный суд апелляционной инстанции в течение десяти дней со дня принятия данного решения.\n\n5. Постановление арбитражного суда апелляционной инстанции по результатам рассмотрения апелляционной жалобы на решение о понуждении юридического лица созвать общее собрание участников может быть обжаловано в арбитражный суд кассационной инстанции в течение десяти дней со дня принятия данного решения.","article_title":"Статья 225.7. Рассмотрение дел о понуждении юридического лица созвать общее собрание участников","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"36078ef1f03a9024272c76552d3b997c2f9e45b25a431e3e8c73f7d87f3aae20"},{"code_id":"APK_RF","article_number":"225.8","version_date":"2002-07-24","article_text":"1. В случаях, предусмотренных федеральным законом, участники юридического лица вправе обратиться в арбитражный суд с иском о возмещении убытков, причиненных этому юридическому лицу. Такие участники пользуются процессуальными правами и несут процессуальные обязанности истца, а также обладают правом требовать принудительное исполнение решения арбитражного суда в пользу этого юридического лица.\n\n2. Решение об удовлетворении требования по иску о возмещении убытков принимается в пользу юридического лица, в интересах которого был предъявлен иск. По ходатайству лица, обратившегося с иском о возмещении убытков, исполнительный лист направляется для исполнения непосредственно арбитражным судом.\n\n3. Судебные расходы, связанные с рассмотрением дела по иску участников юридического лица о возмещении убытков, причиненных юридическому лицу, несут такие участники в равных долях.\n\n4. Возмещение судебных расходов производится по правилам, установленным статьей 110 настоящего Кодекса.","article_title":"Статья 225.8. Рассмотрение дел по спорам о возмещении убытков, причиненных юридическому лицу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2cdbad25feb9c310a81ffdd3eec9231a6e64904a2acbfc79cb1171fe16490c59"},{"code_id":"APK_RF","article_number":"225.9","version_date":"2002-07-24","article_text":"1. Определения арбитражного суда, выносимые при рассмотрении дел по корпоративным спорам, обжалуются по правилам, установленным статьей 188 настоящего Кодекса. Жалобы на такие определения, за исключением определений о прекращении производства по делу и об оставлении заявления без рассмотрения, подаются в арбитражный суд апелляционной инстанции в течение десяти дней со дня их вынесения.\n\n2. Подача жалобы на указанные в части 1 настоящей статьи определения не препятствует рассмотрению дела арбитражным судом и совершению отдельных процессуальных действий по делу.\n\n(Дополнение главой - Федеральный закон от 19.07.2009 № 205-ФЗ)","article_title":"Статья 225.9. Особенности обжалования определений арбитражного суда по корпоративным спорам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5507e79d80191afd852e9257ef23ffc51fcc1d2247af0665b52a3389d870b0cc"},{"code_id":"APK_RF","article_number":"226","version_date":"2002-07-24","article_text":"1. Дела в порядке упрощенного производства рассматриваются арбитражным судом по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными настоящей главой.\n\nПри рассмотрении в порядке упрощенного производства дел, возникающих из административных и иных публичных правоотношений, применяются также особенности, установленные разделом III настоящего Кодекса, при рассмотрении дел с участием иностранных лиц - разделом V настоящего Кодекса, если иное не предусмотрено настоящей главой.\n\nСрок рассмотрения дела в порядке упрощенного производства продлению не подлежит, за исключением случая, предусмотренного частью 3 статьи 253 настоящего Кодекса.","article_title":"Статья 226. Порядок упрощенного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fc15ddb78c30563116c67bd061e1f40e11c2f44bdefad0a0db1939469634b2a4"},{"code_id":"APK_RF","article_number":"227","version_date":"2002-07-24","article_text":"1. В порядке упрощенного производства подлежат рассмотрению дела:\n\n1) по исковым заявлениям о взыскании денежных средств, если цена иска не превышает для юридических лиц один миллион двести тысяч рублей, для индивидуальных предпринимателей - шестьсот тысяч рублей; (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n2) об оспаривании ненормативных правовых актов, решений органов, осуществляющих публичные полномочия, должностных лиц, если в соответствующих ненормативном правовом акте, решении содержится требование об уплате денежных средств или предусмотрено взыскание денежных средств либо обращение взыскания на иное имущество заявителя при условии, что указанные акты, решения оспариваются заявителем в части требования об уплате денежных средств или взыскания денежных средств либо обращения взыскания на иное имущество заявителя и при этом оспариваемая заявителем сумма не превышает сто тысяч рублей;\n\n3) о привлечении к административной ответственности, если за совершение административного правонарушения законом установлено административное наказание в виде предупреждения или административного штрафа, максимальный размер которого не превышает сто тысяч рублей;\n\n4) об оспаривании решений административных органов о привлечении к административной ответственности, если за совершение административного правонарушения назначено административное наказание в виде предупреждения или административного штрафа, размер которого не превышает сто тысяч рублей;\n\n5) о взыскании обязательных платежей и санкций, если указанный в заявлении общий размер подлежащей взысканию денежной суммы не превышает двести тысяч рублей, за исключением дел, рассматриваемых в порядке приказного производства.\n\n2. В порядке упрощенного производства независимо от цены иска подлежат рассмотрению дела:\n\n1) по искам, основанным на представленных истцом документах, устанавливающих денежные обязательства ответчика, которые ответчиком признаются, но не исполняются, и (или) на документах, подтверждающих задолженность по договору, за исключением дел, рассматриваемых в порядке приказного производства;\n\n2) по требованиям, основанным на совершенном нотариусом протесте векселя в неплатеже, неакцепте и недатировании акцепта, за исключением дел, рассматриваемых в порядке приказного производства;\n\n3) по требованиям о взыскании взносов, подлежащих уплате членами некоммерческих организаций, указанных в части 1 статьи 2251 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n3. По ходатайству истца при согласии ответчика или по инициативе суда при согласии сторон в порядке упрощенного производства могут быть рассмотрены также иные дела, если не имеется обстоятельств, указанных в части 5 настоящей статьи.\n\n1) порядок упрощенного производства может привести к разглашению государственной тайны;\n\n2) необходимо выяснить дополнительные обстоятельства или исследовать дополнительные доказательства, а также провести осмотр и исследование доказательств по месту их нахождения, назначить экспертизу или заслушать свидетельские показания;\n\n3) заявленное требование связано с иными требованиями, в том числе к другим лицам, или судебным актом, принятым по данному делу, могут быть нарушены права и законные интересы других лиц.\n\n(Статья в редакции Федерального закона от 28.11.2018 № 451-ФЗ)","article_title":"Статья 227. Дела, рассматриваемые в порядке упрощенного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"36b5e2be5457d0c561120aa6ca788707984243ef6f654a8a9c378ed68ad66a51"},{"code_id":"APK_RF","article_number":"228","version_date":"2002-07-24","article_text":"В определении суд может предложить сторонам урегулировать спор самостоятельно, указав на возможность примирения.\n\nОпределение, вынесенное арбитражным судом по результатам рассмотрения вопроса о принятии искового заявления, заявления, размещается в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" не позднее следующего дня после дня вынесения этого определения. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nСтороны вправе представить в арбитражный суд, рассматривающий дело, и направить друг другу дополнительно документы, содержащие объяснения по существу заявленных требований и возражений в обоснование своей позиции, в срок, который установлен арбитражным судом и не может составлять менее чем тридцать дней со дня вынесения определения о принятии искового заявления, заявления к производству или определения о переходе к рассмотрению дела в порядке упрощенного производства. Такие документы не должны содержать ссылки на доказательства, которые не были раскрыты в установленный судом срок.\n\nПоступившие в арбитражный суд отзыв на исковое заявление, отзыв на заявление, доказательства и иные документы размещаются в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" в режиме ограниченного доступа в срок, не превышающий трех дней со дня их поступления в арбитражный суд. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nПредварительное судебное заседание по делам, рассматриваемым в порядке упрощенного производства, не проводится.\n\nСуд исследует изложенные в представленных сторонами документах объяснения, возражения и (или) доводы лиц, участвующих в деле, и принимает решение на основании доказательств, представленных в течение указанных сроков.\n\nС учетом характера и сложности дела арбитражный суд вправе по своей инициативе или по ходатайству лиц, участвующих в деле, провести судебное заседание с вызовом лиц, участвующих в деле, без перехода к рассмотрению дела по общим правилам искового производства или по правилам административного судопроизводства. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 667-ФЗ)","article_title":"Статья 228. Особенности рассмотрения дел в порядке упрощенного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a0f2961584281e7819ecf3a2c96e649d1f07c60337e69dac43f7899f1e5e3749"},{"code_id":"APK_RF","article_number":"229","version_date":"2002-07-24","article_text":"Принятая по результатам рассмотрения дела резолютивная часть решения размещается в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" не позднее следующего дня после дня ее принятия. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nРешения по делам, возникшим из административных и иных публичных правоотношений и рассматриваемым в порядке упрощенного производства, принимаются арбитражным судом по правилам, предусмотренным статьями 201, 206, 211 и 216 настоящего Кодекса.\n\nЗаявление о составлении мотивированного решения арбитражного суда может быть подано в течение пяти дней со дня размещения решения, принятого в порядке упрощенного производства, в установленном порядке в информационно-телекоммуникационной сети \"Интернет\". В этом случае арбитражным судом решение принимается по правилам, установленным главой 20 настоящего Кодекса, если иное не вытекает из особенностей, установленных настоящей главой. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nМотивированное решение арбитражного суда изготавливается в течение пяти дней со дня поступления от лица, участвующего в деле, соответствующего заявления или со дня подачи апелляционной жалобы. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\nЕсли судья, подписавший резолютивную часть решения, отсутствует в день поступления заявления о составлении мотивированного решения или апелляционной жалобы, вопрос о составлении мотивированного решения указанным судьей разрешается в пятидневный срок, начинающий исчисляться с момента возобновления исполнения указанным судьей своих обязанностей. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\nВ случае составления мотивированного решения арбитражного суда такое решение вступает в законную силу по истечении срока, установленного для подачи апелляционной жалобы.\n\nВ случае подачи апелляционной жалобы решение арбитражного суда первой инстанции, если оно не отменено или не изменено, вступает в законную силу со дня принятия постановления арбитражным судом апелляционной инстанции.\n\nЭто решение, если оно было предметом рассмотрения в арбитражном суде апелляционной инстанции или если арбитражный суд апелляционной инстанции отказал в восстановлении пропущенного срока подачи апелляционной жалобы, и постановление арбитражного суда апелляционной\n\nинстанции, принятое по данному делу, могут быть обжалованы в арбитражный суд кассационной инстанции по основаниям, предусмотренным частью 3 статьи 2882 настоящего Кодекса. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n(Статья в редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n(Дополнение главой - Федеральный закон от 02.03.2016 № 47-ФЗ)","article_title":"Статья 229. Решение по делу, рассматриваемому в порядке упрощенного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fa6dd8bb06ae8e598b4489a0fcbd8ca10eadbc9c9f0ee673679481ed20f4483b"},{"code_id":"APK_RF","article_number":"229.1","version_date":"2002-07-24","article_text":"1. Судебный приказ - судебный акт, вынесенный судьей единолично на основании заявления о взыскании денежных сумм по требованиям взыскателя, предусмотренным статьей 2292 настоящего Кодекса.\n\n2. Судебный приказ является одновременно исполнительным документом и приводится в исполнение в порядке, установленном для исполнения судебных решений.","article_title":"Статья 229.1. Судебный приказ","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4016b378c79ad60c66f4b680744f97be30a91d63bfe756969207d06a8edabaa"},{"code_id":"APK_RF","article_number":"229.2","version_date":"2002-07-24","article_text":"Судебный приказ выдается по делам, в которых:\n\n1) требования вытекают из неисполнения или ненадлежащего исполнения договора и основаны на представленных взыскателем документах, устанавливающих денежные обязательства, если цена заявленных требований не превышает семьсот пятьдесят тысяч рублей; (В редакции  федеральных законов от 28.11.2018 № 451-ФЗ, от 25.12.2023 № 667-ФЗ)\n\n2) требование основано на совершенном нотариусом протесте векселя в неплатеже, неакцепте и недатировании акцепта, если цена заявленного требования не превышает семьсот пятьдесят тысяч рублей; (В редакции  федеральных законов от 28.11.2018 № 451-ФЗ, от 25.12.2023 № 667-ФЗ)\n\n3) заявлено требование о взыскании обязательных платежей и санкций, если указанный в заявлении общий размер подлежащей взысканию денежной суммы не превышает сто тысяч рублей.","article_title":"Статья 229.2. Дела приказного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"19a18cd8982c3bbbe4068a7c81ca8419b0bc7893d8cc945a8d8bd1e7110382a1"},{"code_id":"APK_RF","article_number":"229.3","version_date":"2002-07-24","article_text":"1) наименование арбитражного суда, в который подается заявление;\n\n2) сведения о взыскателе: для взыскателя-гражданина - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, серия и номер водительского удостоверения), для взыскателя-организации - наименование, адрес, идентификационный номер налогоплательщика, реквизиты банковского или казначейского счета и другие необходимые реквизиты; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n3) сведения о должнике: для гражданина-должника - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, место работы (если известно), один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, основной государственный регистрационный номер индивидуального предпринимателя, серия и номер водительского удостоверения); для организации-должника - наименование, адрес, идентификационный номер налогоплательщика и основной государственный регистрационный номер; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n4) требования взыскателя, в том числе период, за который образовалась взыскиваемая задолженность по обязательствам, предусматривающим исполнение по частям или в виде периодических платежей, размер денежной суммы, составляющей платеж, и ее расчет, а также обстоятельства, на которых основаны указанные требования; (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n5) документы, подтверждающие обоснованность требования взыскателя;\n\n6) перечень прилагаемых документов.","article_title":"Статья 229.3. Форма и содержание заявления о выдаче судебного приказа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"34fd3a1965b648039047a595966044d8fc0715bc45041e4b1e40c09324163913"},{"code_id":"APK_RF","article_number":"229.4","version_date":"2002-07-24","article_text":"1. Арбитражный суд возвращает заявление о выдаче судебного приказа в случае нарушения требований к форме и содержанию заявления о выдаче судебного приказа, установленных статьей 2293 настоящего Кодекса, а также в случаях, если:\n\n1) дело неподсудно данному арбитражному суду;\n\n2) не представлены документы, подтверждающие обоснованность требования взыскателя;\n\n3) отклонено ходатайство о предоставлении отсрочки, рассрочки уплаты государственной пошлины или об уменьшении ее размера;\n\n4) от взыскателя поступило ходатайство о возвращении заявления о выдаче судебного приказа.\n\n2. Возвращение заявления о выдаче судебного приказа не является препятствием для повторного обращения взыскателя в арбитражный суд с заявлением к тому же должнику, с тем же требованием и по тем же основаниям после устранения допущенного нарушения.\n\n3. Арбитражный суд отказывает в принятии заявления о выдаче судебного приказа по основаниям, предусмотренным статьей 1271 настоящего Кодекса, а также в случаях, если:\n\n1) заявлено требование, не предусмотренное статьей 2292 настоящего Кодекса;\n\n2) место жительства или место нахождения должника находится вне пределов Российской Федерации;\n\n3) из заявления о выдаче судебного приказа и приложенных к нему документов усматривается наличие спора о праве.\n\n4. О возвращении заявления о выдаче судебного приказа или об отказе в его принятии арбитражный суд в течение трех дней со дня поступления этого заявления в суд выносит определение, которое может быть обжаловано.\n\n(Статья в редакции Федерального закона от 19.12.2016 № 435-ФЗ)","article_title":"Статья 229.4. Основания для возвращения заявления о выдаче судебного приказа или отказа в его принятии","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8ce529ea10083e7ac024946d814466ec80d167bdd82fe96af7c2af341c67ad26"},{"code_id":"APK_RF","article_number":"229.5","version_date":"2002-07-24","article_text":"1. Заявление по делам приказного производства подается в арбитражный суд по общим правилам подсудности, установленным настоящим Кодексом.\n\n2. Судебный приказ по делам приказного производства выносится арбитражным судом в течение десяти дней со дня поступления заявления о выдаче судебного приказа в арбитражный суд.\n\nСудебный приказ выносится без вызова взыскателя и должника и без проведения судебного разбирательства.\n\nСуд исследует изложенные в направленном взыскателем заявлении о выдаче судебного приказа и приложенных к нему документах сведения в обоснование позиции данного лица и выносит судебный приказ на основании представленных документов.\n\nКопия судебного приказа на бумажном носителе в пятидневный срок со дня вынесения судебного приказа высылается должнику, который в течение десяти дней со дня ее получения вправе представить возражения относительно исполнения судебного приказа.\n\nСудебный приказ размещается в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" не позднее следующего дня после дня его вынесения. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nВ определении суда об отмене судебного приказа указывается, что заявленное взыскателем требование может быть предъявлено в порядке искового производства либо производства по делам, возникающим из административных и иных публичных правоотношений.\n\nКопии определения суда об отмене судебного приказа направляются взыскателю и должнику в срок, не превышающий пяти дней со дня вынесения указанного определения. Указанное определение размещается в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" не позднее следующего дня после дня его вынесения. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nО возвращении документов, содержащих возражения должника, суд выносит определение.\n\nСудебный приказ может быть направлен судом для исполнения в форме электронного документа, подписанного судьей усиленной квалифицированной электронной подписью в порядке, установленном законодательством Российской Федерации.\n\n(Статья в редакции Федерального закона от 23.06.2016 № 220-ФЗ)","article_title":"Статья 229.5. Порядок приказного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c373df54377007475b696404da3032e4cd1cf499dd7c6c5cd1c1732c9f23f462"},{"code_id":"APK_RF","article_number":"229.6","version_date":"2002-07-24","article_text":"1. В судебном приказе указываются:\n\n1) номер дела и дата вынесения судебного приказа;\n\n2) наименование арбитражного суда, фамилия и инициалы судьи, вынесшего судебный приказ;\n\n3) сведения о взыскателе: для гражданина-взыскателя - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, серия и номер водительского удостоверения); для организации-взыскателя - наименование, адрес, идентификационный номер налогоплательщика; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n4) сведения о должнике, содержащиеся в заявлении о выдаче судебного приказа: для гражданина-должника - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, место работы (если известно), один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, основной государственный регистрационный номер индивидуального предпринимателя, серия и номер водительского удостоверения); для организации-должника - наименование, адрес, идентификационный номер налогоплательщика и основной государственный регистрационный номер; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n5) законы и иные нормативные правовые акты, которыми руководствовался суд при удовлетворении требования;\n\n6) размер денежных сумм, подлежащих взысканию;\n\n7) размер неустойки, если ее взыскание предусмотрено федеральным законом или договором, а также размер пеней, если таковые причитаются;\n\n8) сумма государственной пошлины, подлежащая взысканию с должника в пользу взыскателя или в доход соответствующего бюджета;\n\n9) реквизиты банковского счета взыскателя, на который должны быть перечислены средства, подлежащие взысканию, в случае, если обращение взыскания производится на средства бюджетов бюджетной системы Российской Федерации;\n\n10) период, за который образовалась взыскиваемая задолженность по обязательствам, предусматривающим исполнение по частям или в виде периодических платежей.\n\n(Наименование в редакции Федерального закона от 29.12.2015 № 409-ФЗ)\n\n(Параграф в редакции Федерального закона от 29.12.2015 № 409-ФЗ)","article_title":"Статья 229.6. Содержание судебного приказа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f843304c0e3ff439d6532942cb0372c4aeabb512f09ddf35668822db297e172f"},{"code_id":"APK_RF","article_number":"23","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\nОснованием для отвода эксперта является также проведение им ревизии или проверки, материалы которых стали поводом для обращения в арбитражный суд или используются при рассмотрении дела.","article_title":"Статья 23. Отвод помощника судьи, секретаря судебного заседания, эксперта, специалиста, переводчика","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5727f6a98ef2e99af7a4fb425e906446cc7d5b0fd7087b47761de28d34836102"},{"code_id":"APK_RF","article_number":"230","version_date":"2002-07-24","article_text":"1. Правила, установленные настоящим параграфом, применяются при рассмотрении арбитражным судом заявлений об оспаривании решений третейских судов и международных коммерческих арбитражей (третейских судов) с местом арбитража на территории Российской Федерации.\n\n2. Оспаривание в арбитражном суде решений третейских судов по спорам, возникающим из гражданских правоотношений при осуществлении предпринимательской и иной экономической деятельности, может быть осуществлено лицами, участвующими в третейском разбирательстве, а также иными лицами, в отношении прав и обязанностей которых вынесено решение третейского суда, путем подачи заявления в арбитражный суд об отмене решения третейского суда в соответствии со статьей 233 настоящего Кодекса.\n\n3. С заявлением об отмене решения третейского суда вправе обратиться прокурор по делам, предусмотренным абзацами третьим и четвертым части 1 статьи 52 настоящего Кодекса, если решение третейского суда затрагивает интересы Российской Федерации, субъекта Российской Федерации, муниципального образования, не участвовавших в третейском разбирательстве.\n\n4. Заявление об отмене решения третейского суда подается в арбитражный суд субъекта Российской Федерации, на территории которого принято решение третейского суда, в срок, не превышающий трех месяцев со дня получения оспариваемого решения стороной третейского разбирательства, обратившейся с заявлением, если иное не установлено международным договором Российской Федерации или федеральным законом. По соглашению сторон третейского разбирательства заявление об отмене решения третейского суда может быть подано в арбитражный суд субъекта Российской Федерации по месту нахождения одной из указанных сторон.\n\n5. Лицо, которое не является стороной третейского разбирательства и в отношении прав и обязанностей которого вынесено решение третейского суда, а также прокурор в случаях, установленных настоящей статьей, вправе подать заявление об отмене такого решения в арбитражный суд субъекта Российской Федерации, на территории которого принято решение третейского суда, в срок, не превышающий трех месяцев со дня, когда указанное лицо узнало или должно было узнать об оспариваемом им решении третейского суда.\n\n6. Заявление об отмене решения третейского суда оплачивается государственной пошлиной в размере, предусмотренном федеральным законом для оплаты заявления о выдаче исполнительного листа на принудительное исполнение решения третейского суда.","article_title":"Статья 230. Оспаривание решений третейских судов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"91bb80a9259832aff79d77c98046276e9cafb674f93e82a5b04bda4f27e6053e"},{"code_id":"APK_RF","article_number":"231","version_date":"2002-07-24","article_text":"1) наименование арбитражного суда, в который подается заявление;\n\n2) состав третейского суда, принявшего решение, его место нахождения, наименование постоянно действующего арбитражного учреждения, администрировавшего соответствующее третейское разбирательство, его место нахождения (в случае наличия постоянно действующего арбитражного учреждения);\n\n3) наименования сторон третейского разбирательства, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n4) дата и место принятия решения третейского суда;\n\n5) дата получения оспариваемого решения третейского суда стороной, обратившейся с заявлением об отмене указанного решения, либо дата, когда лицо, которое не является стороной третейского разбирательства и в отношении прав и обязанностей которого вынесено решение третейского суда, узнало об оспариваемом им решении;\n\n6) требование заявителя об отмене решения третейского суда, а также основания, по которым оспаривается указанное решение.\n\n1) копия решения третейского суда, подписанного арбитрами и направленного стороне третейского разбирательства в соответствии с федеральным законом;\n\n2) подлинное соглашение о третейском разбирательстве или его надлежащим образом заверенная копия;\n\n3) документы, представляемые в обоснование требования об отмене решения третейского суда;\n\n4) документ, подтверждающий уплату государственной пошлины в порядке и в размере, которые установлены федеральным законом;\n\n5) уведомление о вручении или иной документ, подтверждающий направление копии заявления об отмене решения третейского суда другой стороне третейского разбирательства;\n\n6) доверенность или иной документ, подтверждающие полномочия лица на подписание заявления.","article_title":"Статья 231. Требования к заявлению об отмене решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"84d48a7d25d684d76b685a99ade28164d4cde93897fc0a189a3fddcd0f43aff8"},{"code_id":"APK_RF","article_number":"232","version_date":"2002-07-24","article_text":"1. Заявление об отмене решения третейского суда рассматривается судьей единолично по правилам рассмотрения дела арбитражным судом первой инстанции, предусмотренным настоящим Кодексом, с учетом особенностей, установленных настоящим параграфом, в срок, не превышающий одного месяца со дня его поступления в ар\n\nбитражный суд субъекта Российской Федерации.\n\n2. При подготовке дела об отмене решения третейского суда к судебному разбирательству по ходатайству лиц, участвующих в деле, арбитражный суд может истребовать материалы дела, решение по которому оспаривается в арбитражном суде, из постоянно действующего арбитражного учреждения, в котором находятся на хранении материалы третейского дела, или из органа, уполномоченного на хранение материалов третейского дела в соответствии с законодательством Российской Федерации, по правилам, предусмотренным настоящим Кодексом для истребования доказательств.\n\n3. При рассмотрении заявления об отмене решения третейского суда, поданного лицом, которое не является стороной третейского разбирательства и в отношении прав и обязанностей которого вынесено решение третейского суда, арбитражный суд обязан привлечь к участию в деле все стороны третейского разбирательства.\n\n4. Лица, участвующие в деле об отмене решения третейского суда, извещаются арбитражным судом о времени и месте судебного заседания. Неявка указанных лиц, извещенных надлежащим образом о времени и месте проведения судебного заседания, не является препятствием для рассмотрения дела.\n\n5. Если заявление об отмене решения третейского суда подано по основаниям, связанным с тем, что сторона третейского разбирательства не была должным образом уведомлена о назначении третейского судьи или о третейском разбирательстве, в том числе о времени и месте заседания третейского суда, или по другим уважительным причинам не могла представить свои объяснения, либо что решение третейского суда вынесено по спору, не предусмотренному третейским соглашением или не подпадающему под его условия, или содержит постановления по вопросам, выходящим за пределы третейского соглашения, либо что состав третейского суда или арбитражная процедура не соответствовали соглашению сторон или федеральному закону, арбитражный суд по ходатайству стороны третейского разбирательства вправе приостановить производство по делу об отмене решения третейского суда на срок, не превышающий трех месяцев, с тем чтобы третейский суд возобновил третейское разбирательство и устранил основания для отмены арбитражного решения. После возобновления производства по делу об отмене решения третейского суда арбитражный суд рассматривает заявление об отмене решения третейского суда с учетом действий, предпринятых третейским судом в целях устранения оснований для отмены арбитражного решения.\n\n6. При рассмотрении дела арбитражный суд в судебном заседании устанавливает наличие или отсутствие оснований для отмены решения третейского суда, предусмотренных статьей 233 настоящего Кодекса, путем исследования представленных в суд доказательств в обоснование заявленных требований и возражений, но не вправе переоценивать обстоятельства, установленные третейским судом, либо пересматривать решение третейского суда по существу.","article_title":"Статья 232. Порядок рассмотрения заявления об отмене решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9d38d845307fc4d641bec8c84d1b4d8f5e6afd8b81ef6d072d46e108f524ae19"},{"code_id":"APK_RF","article_number":"233","version_date":"2002-07-24","article_text":"1. Решение третейского суда может быть отменено арбитражным судом только в случаях, предусмотренных настоящей статьей.\n\n2. Решение третейского суда может быть отменено арбитражным судом по основаниям, установленным частями 3 и 4 настоящей статьи. Решение третейского суда может быть отменено по основаниям, установленным частью 4 настоящей статьи, даже в том случае, если сторона, подавшая заявление об отмене такого решения, не ссылается на указанные основания.\n\n3. Решение третейского суда может быть отменено арбитражным судом лишь в случае, если сторона, подающая заявление об отмене такого решения, представит доказательства того, что:\n\n1) одна из сторон третейского соглашения, на основании которого спор был разрешен третейским судом, не обладала полной дееспособностью;\n\n2) третейское соглашение, на основании которого спор был разрешен третейским судом, недействительно по праву, которому стороны его подчинили, а при отсутствии такого указания - по праву Российской Федерации;\n\n3) решение третейского суда вынесено по спору, не предусмотренному третейским соглашением или не подпадающему под его условия, или содержит постановления по вопросам, выходящим за пределы третейского соглашения. Если постановления третейского суда по вопросам, которые охватываются третейским соглашением, могут быть отделены от постановлений по вопросам, которые не охватываются таким соглашением, может быть отменена только та часть решения, которая содержит постановления по вопросам, не охватываемым третейским соглашением;\n\n4) состав третейского суда или процедура арбитража не соответствовали соглашению сторон или федеральному закону;\n\n5) сторона, против которой принято решение третейского суда, не была должным образом уведомлена об избрании (назначении) третейских судей или о времени и месте заседания третейского суда либо по другим уважительным причинам не могла представить в третейский суд свои объяснения.\n\n4. Арбитражный суд отменяет решение третейского суда, если установит, что:\n\n1) спор, рассмотренный третейским судом, в соответствии с федеральным законом не может быть предметом третейского разбирательства;\n\n2) решение третейского суда противоречит публичному порядку Российской Федерации. Если часть решения третейского суда, которая противоречит публичному порядку Российской Федерации, может быть отделена от той части, которая ему не противоречит, может быть отменена только та часть решения третейского суда, которая противоречит публичному порядку Российской Федерации.\n\n5. Решение международного коммерческого арбитража может быть отменено арбитражным судом по основаниям, предусмотренным международным договором Российской Федерации и федеральным законом о международном коммерческом арбитраже.","article_title":"Статья 233. Основания для отмены решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"63b8331c9ad38813b4542def466cfd0a302e7709f3033e9c800dd21f43a8052f"},{"code_id":"APK_RF","article_number":"234","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения заявления об отмене решения третейского суда арбитражный суд выносит определение по правилам, установленным главой 20 настоящего Кодекса для принятия решения.\n\n2. В определении арбитражного суда по делу об оспаривании решения третейского суда должны содержаться:\n\n1) сведения об оспариваемом решении третейского суда и о месте его принятия;\n\n2) сведения о составе третейского суда, принявшего оспариваемое решение;\n\n3) наименования сторон третейского разбирательства;\n\n4) указание на отмену решения третейского суда полностью или в части либо отказ в удовлетворении требования заявителя полностью или в части;\n\n5) в случае отказа в удовлетворении требования заявителя об отмене решения третейского суда полностью или в части указание на возможность получения лицом, в пользу которого вынесено такое решение, исполнительного листа на принудительное исполнение решения третейского суда в порядке, предусмотренном статьей 319 настоящего Кодекса (за исключением случая, предусмотренного пунктом 3 части 7 статьи 238 настоящего Кодекса, если иным арбитражным судом Российской Федерации вынесено определение о выдаче исполнительного листа на принудительное исполнение того же решения третейского суда).\n\n3. Отмена решения третейского суда не препятствует сторонам третейского разбирательства повторно обратиться в третейский суд, если возможность обращения в третейский суд не утрачена, или в арбитражный суд по общим правилам, предусмотренным настоящим Кодексом.\n\n4. В случае, если решение третейского суда отменено арбитражным судом полностью или в части вследствие недействительности третейского соглашения, либо оно было принято по спору, не предусмотренному третейским соглашением или не подпадающему под его условия, либо содержит постановления по вопросам, не охватываемым третейским соглашением, а также если решение третейского суда отменено арбитражным судом в связи с тем, что спор, рассмотренный третейским судом, не может быть предметом третейского разбирательства в соответствии с федеральным законом или решение третейского суда нарушает публичный порядок Российской Федерации, стороны третейского разбирательства могут обратиться за разрешением такого спора в арбитражный суд по общим правилам, предусмотренным настоящим Кодексом.\n\n5. Определение арбитражного суда по делу об оспаривании решения третейского суда может быть обжаловано в кассационном порядке в арбитражный суд округа в течение одного месяца со дня вынесения определения.","article_title":"Статья 234. Определение арбитражного суда по делу об оспаривании решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c5f2439d2dcf6863e6566049a731114595695d1c387f136cf853d579428b726d"},{"code_id":"APK_RF","article_number":"235","version_date":"2002-07-24","article_text":"1. В случаях, предусмотренных федеральным законом, любая сторона третейского разбирательства может обратиться в арбитражный суд субъекта Российской Федерации, на территории которого проводится третейское разбирательство, с заявлением об отмене постановления третейского суда предварительного характера о наличии у него компетенции.\n\n2. Заявление по вопросу компетенции третейского суда может быть подано в течение одного месяца после получения стороной третейского разбирательства постановления третейского суда, указанного в части 1 настоящей статьи.\n\n3. Арбитражный суд рассматривает заявление по вопросу компетенции третейского суда по правилам, предусмотренным настоящим параграфом.\n\n4. Если к моменту рассмотрения арбитражным судом заявления по вопросу компетенции третейского суда будет вынесено решение третейского суда по тому же спору, указанное заявление подлежит оставлению без рассмотрения в связи с завершением третейского разбирательства. В этом случае сторона третейского разбирательства, подавшая заявление по вопросу компетенции третейского суда, не лишена права ссылаться на обстоятельства, являющиеся основанием для указанного заявления, при рассмотрении арбитражным судом заявления об отмене или о выдаче исполнительного листа на принудительное исполнение решения третейского суда по тому же спору.\n\n5. По результатам рассмотрения заявления по вопросу компетенции третейского суда арбитражный суд выносит определение об отмене постановления третейского суда о наличии у него компетенции или об отказе в удовлетворении требования заявителя.\n\n6. Определение арбитражного суда, указанное в части 5 настоящей статьи, не может быть обжаловано.\n\n(Параграф в редакции Федерального закона от 29.12.2015 № 409-ФЗ)","article_title":"Статья 235. Рассмотрение заявления по вопросу компетенции третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57fc99e2451f014722af4e14b4759449669a319d6eec939c512a5f2238b2e56f"},{"code_id":"APK_RF","article_number":"236","version_date":"2002-07-24","article_text":"1. Правила, установленные настоящим параграфом, применяются при рассмотрении арбитражным судом заявлений о выдаче исполнительных листов на принудительное исполнение принятых на территории Российской Федерации решений третейских судов и международных коммерческих арбитражей (третейских судов).\n\n2. Вопрос о выдаче исполнительного листа на принудительное исполнение решения третейского суда по спору, возникшему из гражданских правоотношений при осуществлении предпринимательской и иной экономической деятельности, рассматривается арбитражным судом по заявлению стороны третейского разбирательства, в пользу которой принято решение третейского суда.","article_title":"Статья 236. Выдача исполнительного листа на принудительное исполнение решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d659218c91f0e62b9e559fb5943a5e3d4a0aba84f879061f123af88f81a5fc34"},{"code_id":"APK_RF","article_number":"237","version_date":"2002-07-24","article_text":"1) наименование арбитражного суда, в который подается заявление;\n\n2) состав третейского суда, принявшего решение, его место нахождения, наименование постоянно действующего арбитражного учреждения, администрировавшего соответствующее третейское разбирательство, его место нахождения (в случае наличия постоянно действующего арбитражного учреждения);\n\n3) наименования сторон третейского разбирательства, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n4) дата и место принятия решения третейского суда;\n\n5) требование заявителя о выдаче исполнительного листа на принудительное исполнение решения третейского суда.\n\n1) копия подписанного арбитрами решения третейского суда, заверенная постоянно действующим арбитражным учреждением, нотариально удостоверенная копия решения третейского суда, образованного сторонами для разрешения конкретного спора;\n\n2) подлинное соглашение о третейском разбирательстве или его надлежащим образом заверенная копия;\n\n3) документ, подтверждающий уплату государственной пошлины в порядке и в размере, которые установлены федеральным законом;\n\n4) уведомление о вручении или иной документ, подтверждающие направление копии заявления о выдаче исполнительного листа на принудительное исполнение решения третейского суда другой стороне третейского разбирательства;\n\n5) доверенность или иной документ, подтверждающие полномочия лица на подписание заявления.","article_title":"Статья 237. Требования к заявлению о выдаче исполнительного листа на принудительное исполнение решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3cf1f998230411ab1518eb4b7be9652c38149f1bffcc699b50ca9a064087357b"},{"code_id":"APK_RF","article_number":"238","version_date":"2002-07-24","article_text":"1. Заявление о выдаче исполнительного листа на принудительное исполнение решения третейского суда рассматривается судьей единолично по правилам рассмотрения дела арбитражным судом первой инстанции, предусмотренным настоящим Кодексом, с учетом особенностей, установленных настоящим параграфом, в срок, не превышающий одного месяца со дня его поступления в арбитражный суд субъекта Российской Федерации.\n\n2. При подготовке дела к судебному разбирательству по ходатайству стороны третейского разбирательства суд может истребовать из постоянно действующего арбитражного учреждения или из органа, уполномоченного на хранение материалов третейского дела в соответствии с законодательством Российской Федерации, материалы дела, по которому испрашивается исполнительный лист на принудительное исполнение решения третейского суда, по правилам, предусмотренным настоящим Кодексом для истребования доказательств.\n\n3. Стороны третейского разбирательства извещаются арбитражным судом о времени и месте судебного заседания. Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения дела.\n\n4. При рассмотрении дела арбитражный суд в судебном заседании устанавливает наличие или отсутствие оснований для отказа в выдаче исполнительного листа на принудительное исполнение решения третейского суда, предусмотренных статьей 239 настоящего Кодекса, путем исследования представленных в суд доказательств обоснования заявленных требований и возражений, но не вправе переоценивать обстоятельства, установленные третейским судом, либо пересматривать решение третейского суда по существу.\n\n5. Если в одном и том же арбитражном суде находятся на рассмотрении заявление о выдаче исполнительного листа на принудительное исполнение решения третейского суда и заявление о его отмене, арбитражный суд объединяет указанные дела в одно производство в порядке, предусмотренном частями 21 и 6 статьи 130 настоящего Кодекса.\n\n6. Если в различных арбитражных судах Российской Федерации находятся на рассмотрении заявление о выдаче исполнительного листа на принудительное исполнение решения третейского суда и заявление о его отмене, арбитражный суд, в котором рассматривается то из указанных заявлений, которое было подано позднее, обязан приостановить возбужденное им производство в соответствии с пунктом 1 части 1 статьи 143 настоящего Кодекса до рассмотрения иным арбитражным судом того из указанных заявлений, которое было подано первым. В случае, если в различных арбитражных судах Российской Федерации находятся на рассмотрении поданные в один и тот же день заявление о выдаче исполнительного листа на принудительное исполнение решения третейского суда и заявление о его отмене, по правилам, установленным настоящей частью, подлежит приостановлению производство по делу о выдаче исполнительного листа на принудительное исполнение решения третейского суда.\n\n7. После возобновления производства по делу, которое было приостановлено в соответствии с положениями части 6 настоящей статьи, арбитражный суд выносит определение:\n\n1) об отказе в выдаче исполнительного листа на принудительное исполнение решения третейского суда в случае вынесения иным арбитражным судом Российской Федерации определения об отмене этого решения;\n\n2) о прекращении производства по заявлению о выдаче исполнительного листа на принудительное исполнение решения третейского суда в соответствии с пунктом 2 части 1 статьи 150 настоящего Кодекса в случае вынесения иным арбитражным судом Российской Федерации определения об отказе в отмене этого решения с учетом положений пункта 5 части 2 статьи 234 настоящего Кодекса;\n\n3) об отказе в отмене решения третейского суда в случае вынесения иным арбитражным судом Российской Федерации определения о выдаче исполнительного листа на принудительное исполнение этого решения;\n\n4) о прекращении производства по заявлению об отмене решения третейского суда по правилам, предусмотренным пунктом 2 части 1 статьи 150 настоящего Кодекса, в случае вынесения иным арбитражным судом Российской Федерации определения об отказе в выдаче исполнительного листа на принудительное исполнение этого решения.\n\n8. В случае, если арбитражный суд, рассматривающий заявление об отмене решения третейского суда или о приведении этого решения в исполнение, приостановит производство по делу, чтобы третейский суд возобновил третейско\n\nе разбирательство и устранил основания для отмены решения третейского суда или отказа в его принудительном исполнении, третейский суд может возобновить третейское разбирательство по ходатайству любой стороны, поданному в течение срока такого приостановления дела в арбитражном суде.","article_title":"Статья 238. Порядок рассмотрения заявлений о выдаче исполнительного листа на принудительное исполнение решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"81b4bd192547b32ee378ab47991cdd520c2988ac01d6526c82dd03a930aab1bd"},{"code_id":"APK_RF","article_number":"239","version_date":"2002-07-24","article_text":"1. Арбитражный суд может отказать в выдаче исполнительного листа на принудительное исполнение решения третейского суда только в случаях, предусмотренных настоящей статьей.\n\n2. В выдаче исполнительного листа на принудительное исполнение решения третейского суда может быть отказано по основаниям, установленным частями 3 и 4 настоящей статьи. В выдаче исполнительного листа на принудительное исполнение решения третейского суда может быть отказано по основаниям, установленным частью 4 настоящей статьи, даже в том случае, если сторона, против которой вынесено решение, не ссылается на указанные основания.\n\n3. Арбитражный суд может отказать в выдаче исполнительного листа на принудительное исполнение решения третейского суда, если сторона третейского разбирательства, против которой вынесено решение третейского суда, представит доказательства того, что:\n\n1) одна из сторон третейского соглашения, на основании которого спор разрешен третейским судом, не обладала полной дееспособностью;\n\n2) третейское соглашение, на основании которого спор был разрешен третейским судом, недействительно по праву, которому стороны его подчинили, а при отсутствии такого указания по праву Российской Федерации;\n\n3) сторона, против которой вынесено решение, не была должным образом уведомлена о назначении третейского судьи или о третейском разбирательстве, в том числе о времени и месте заседания третейского суда, либо по другим уважительным причинам не могла представить в третейский суд свои объяснения;\n\n4) решение третейского суда вынесено по спору, не предусмотренному третейским соглашением или не подпадающему под его условия, либо содержит постановления по вопросам, выходящим за пределы третейского соглашения, и что если постановления по вопросам, охватываемым третейским соглашением, могут быть отделены от тех, которые не охватываются таким соглашением, та часть решения третейского суда, в которой содержатся постановления по вопросам, охватываемым третейским соглашением, может быть признана и приведена в исполнение;\n\n5) состав третейского суда или процедура арбитража не соответствовали соглашению сторон или федеральному закону.\n\n4. Арбитражный суд отказывает в выдаче исполнительного листа на принудительное исполнение решения третейского суда, если установит, что:\n\n1) спор, рассмотренный третейским судом, в соответствии с федеральным законом не может быть предметом третейского разбирательства;\n\n2) приведение в исполнение решения третейского суда противоречит публичному порядку Российской Федерации. Если часть решения третейского суда, которая противоречит публичному порядку Российской Федерации, может быть отделена от той части, которая ему не противоречит, та часть решения, которая не противоречит публичному порядку Российской Федерации, может быть признана или приведена в исполнение.\n\n5. Арбитражный суд может отказать в выдаче исполнительного листа на принудительное исполнение решения международного коммерческого арбитража по основаниям, предусмотренным международным договором Российской Федерации и федеральным законом о международном коммерческом арбитраже.","article_title":"Статья 239. Основания отказа в выдаче исполнительного листа на принудительное исполнение решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b25208fc6d082f38c62517d8109c66d49d7d2db7481057d1a82f8c8ac0298183"},{"code_id":"APK_RF","article_number":"24","version_date":"2002-07-24","article_text":"В ходе рассмотрения дела заявление о самоотводе или об отводе допускается только в случае, если основание самоотвода или отвода стало известно лицу, заявляющему самоотвод или отвод, после начала рассмотрения дела по существу.","article_title":"Статья 24. Заявления о самоотводах и об отводах","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a7f6e22434f44b45f793513fb9306d7dbc9877f59e6fdf72690a3f4e227ac2ce"},{"code_id":"APK_RF","article_number":"240","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения заявления о выдаче исполнительного листа на принудительное исполнение решения третейского суда арбитражный суд выносит определение в порядке, установленном главой 20 настоящего Кодекса для принятия решения.\n\n2. В определении по делу о выдаче исполнительного листа на принудительное исполнение решения третейского суда должны содержаться:\n\n1) сведения о составе третейского суда, принявшего это решение;\n\n2) наименование постоянно действующего арбитражного учреждения, администрировавшего третейское разбирательство, его место нахождения (в случае наличия постоянно действующего арбитражного учреждения);\n\n3) наименования сторон третейского разбирательства;\n\n4) сведения о решении третейского суда, о выдаче исполнительного листа на принудительное исполнение которого ходатайствует заявитель;\n\n5) указание на выдачу исполнительного листа на принудительное исполнение решения третейского суда или отказ в выдаче исполнительного листа.\n\n3. Отказ в выдаче исполнительного листа на принудительное исполнение решения третейского суда не является препятствием для повторного обращения в третейский суд, если возможность обращения в третейский суд не утрачена, или в арбитражный суд по общим правилам, предусмотренным настоящим Кодексом.\n\n4. В случае, если в выдаче исполнительного листа на принудительное исполнение решения третейского суда отказано арбитражным судом полностью или в части вследствие недействительности соглашения о третейском разбирательстве либо решение было принято по спору, не предусмотренному третейским соглашением, или не подпадает под его условия, или содержит постановления по вопросам, не охватываемым соглашением о третейском разбирательстве, а также если спор, рассмотренный третейским судом, не может быть предметом третейского разбирательства в соответствии с федеральным законом или решение третейского суда противоречит публичному порядку Российской Федерации, стороны третейского разбирательства могут обратиться за разрешением такого спора в арбитражный суд по общим правилам, предусмотренным настоящим Кодексом.\n\n5. Определение арбитражного суда по делу о выдаче исполнительного листа на принудительное исполнение решения третейского суда может быть обжаловано в кассационном порядке в арбитражный суд округа в течение одного месяца со дня вынесения определения.\n\n(Дополнение параграфом - Федеральный закон от 29.12.2015 № 409-ФЗ)","article_title":"Статья 240. Определение арбитражного суда по делу о выдаче исполнительного листа на принудительное исполнение решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a94c97f165eecb438210bea0f43deecf6034bd0f453cc725eb784443d2701df4"},{"code_id":"APK_RF","article_number":"240.1","version_date":"2002-07-24","article_text":"1. Правила, установленные настоящим параграфом, применяются при осуществлении арбитражным судом функций содействия в отношении третейского разбирательства, осуществляемого на территории Российской Федерации.\n\n2. В соответствии с настоящим параграфом арбитражный суд осуществляет следующие функции содействия в отношении третейских судов по спорам, возникающим из гражданских правоотношений при осуществлении предпринимательской и иной экономической деятельности:\n\n1) разрешение вопросов, связанных с отводом третейского судьи;\n\n2) разрешение вопросов, связанных с назначением третейского судьи;\n\n3) разрешение вопросов, связанных с прекращением полномочий третейского судьи.\n\n3. Арбитражный суд осуществляет функции, указанные в части 2 настоящей статьи, только в случаях, предусмотренных федеральным законом.\n\n4. Арбитражный суд осуществляет функции, указанные в части 2 настоящей статьи, на основании заявления, поданного лицом или лицами, участвующими в третейском разбирательстве.\n\n5. Заявление, указанное в части 4 настоящей статьи, подается в арбитражный суд субъекта Российской Федерации, на территории которого проводится соответствующее третейское разбирательство, в срок, не превышающий одного месяца со дня, когда лицу, подающему заявление, стало известно или должно было стать известно об обстоятельствах, являющихся основанием для подачи заявления.\n\n6. Заявление, указанное в части 4 настоящей статьи, оплачивается государственной пошлиной в размере, предусмотренном федеральным законом для оплаты искового заявления неимущественного характера.","article_title":"Статья 240.1. Дела, связанные с выполнением арбитражными судами функций содействия в отношении третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"60bca7646c172e9a19e9ee237da28194fa4e0a55eae87e716dd50bab440a110f"},{"code_id":"APK_RF","article_number":"240.2","version_date":"2002-07-24","article_text":"1) наименование арбитражного суда, в который подается заявление о содействии;\n\n2) состав третейского суда, рассматривающего спор, его место нахождения, наименование постоянно действующего арбитражного учреждения, администрирующего третейское разбирательство, его место нахождения (в случае наличия постоянно действующего арбитражного учреждения);\n\n3) наименования сторон третейского разбирательства, их место нахождения или место жительства;\n\n4) сведения о третейском судье (третейских судьях), в отношении которого подается заявление о содействии (если применимо);\n\n5) указание на обстоятельства, являющиеся основанием для обращения заявителя в арбитражный суд за содействием в отношении третейского суда, а также на нормы федерального закона, предусматривающие выполнение арбитражным судом тех функций, за выполнением которых обращается заявитель;\n\n6) требование заявителя и основания требования.\n\n1) надлежащим образом заверенная копия искового заявления в третейский суд с доказательствами его получения ответчиком. Копии указанных документов могут быть заверены председателем постоянно действующего арбитражного учреждения, администрирующего соответствующее третейское разбирательство, или нотариально удостоверены;\n\n2) подлинное соглашение о третейском разбирательстве или его надлежащим образом заверенная копия;\n\n3) документы, подтверждающие обстоятельства, являющиеся основанием для обращения заявителя в арбитражный суд за содействием в отношении третейского суда;\n\n4) документы, представляемые в обоснование требования заявителя;\n\n5) документ, подтверждающий уплату государственной пошлины в порядке и в размере, которые установлены федеральным законом;\n\n6) доверенность или иной документ, подтверждающие полномочия лица на подписание заявления о содействии.","article_title":"Статья 240.2. Требования к заявлению о выполнении арбитражными судами функций содействия в отношении третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"16db74f2fae8ca357085a436663e3fb725f3c70e33f330f5bdf731b59f00fa29"},{"code_id":"APK_RF","article_number":"240.3","version_date":"2002-07-24","article_text":"1. Заявление о содействии рассматривается единолично судьей арбитражного суда субъекта Российской Федерации по правилам рассмотрения дела арбитражным судом первой инстанции, предусмотренным настоящим Кодексом, с особенностями, установленными настоящим параграфом и федеральным законом, в срок, не превышающий одного месяца со дня поступления заявления о содействии в арбитражный суд субъекта Российской Федерации.\n\n2. Стороны третейского разбирательства извещаются арбитражным судом о времени и месте судебного заседания. Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения дела.\n\n3. При рассмотрении дела арбитражный суд в судебном заседании устанавливает наличие или отсутствие оснований для удовлетворения требований заявителя путем исследования представленных в суд доказательств в обоснование заявленных требований и возражений.\n\n4. Если к моменту рассмотрения арбитражным судом заявления о содействии для решения вопроса, указанного в пункте 1 части 2 статьи 2401 настоящего Кодекса, будет вынесено решение третейского суда по соответствующему спору, заявление о содействии подлежит оставлению без рассмотрения в связи с завершением третейского разбирательства. В этом случае сторона третейского разбирательства, подавшая заявление о содействии, не лишена права ссылаться на обстоятельства, являющиеся основанием заявления о содействии, при рассмотрении арбитражным судом заявления об отмене или о выдаче исполнительного листа на принудительное исполнение решения третейского суда по тому же спору.\n\n5. Судья, выполнявший функции содействия в отношении третейского суда, указанные в части 2 статьи 2401 настоящего Кодекса, не вправе участвовать в рассмотрении заявления об отмене или о выдаче исполнительного листа на принудительное исполнение решения третейского суда по соответствующему спору в соответствии с пунктом 1 части 1 статьи 21 настоящего Кодекса.","article_title":"Статья 240.3. Порядок рассмотрения заявления о содействии","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b131b83d346a54f510819318f7f9ffe9550594715a8abd73f6a9ccb039ef62d2"},{"code_id":"APK_RF","article_number":"240.4","version_date":"2002-07-24","article_text":"1. Заявление по вопросу об отводе третейского судьи подлежит удовлетворению арбитражным судом при наличии одновременно следующих обстоятельств:\n\n1) соблюдена процедура отвода третейского судьи, которая установлена сторонами или федеральным законом и согласно которой вопрос об отводе третейского судьи передан на разрешение арбитражного суда;\n\n2) имеются основания для отвода третейского судьи, установленные федеральным законом.\n\n2. Заявление по вопросу о назначении третейского судьи подлежит удовлетворению арбитражным судом при наличии одновременно следующих обстоятельств:\n\n1) соблюдена процедура назначения третейского судьи, которая установлена сторонами или федеральным законом и согласно которой вопрос о назначении третейского судьи передан на разрешение арбитражного суда;\n\n2) в соответствии с федеральным законом арбитражный суд полномочен решить вопрос, связанный с назначением третейского судьи.\n\n3. Заявление по вопросу о прекращении полномочий третейского судьи подлежит удовлетворению арбитражным судом при наличии одновременно следующих обстоятельств:\n\n1) соблюдена процедура прекращения полномочий третейского судьи, которая установлена сторонами или федеральным законом и согласно которой вопрос о прекращении полномочий третейского судьи передан на разрешение арбитражного суда;\n\n2) имеются основания для прекращения полномочий третейского судьи, предусмотренные федеральным законом.","article_title":"Статья 240.4. Основания для удовлетворения заявления о содействии","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4403a05e20baf2305b8b0971ad679d326352c56bfff63faa3d5357b8333eb849"}]$law7v002$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
